# Week 6: Solutions

## Exercise 1 Solution: Factory Pattern

```python
from typing import Dict, Type, Any, Optional, Protocol, runtime_checkable, List, Callable
import json


@runtime_checkable
class Parser(Protocol):
    """Protocol for all parsers."""

    @property
    def name(self) -> str: ...

    @property
    def file_extensions(self) -> List[str]: ...

    def parse(self, raw: str) -> Any: ...


class ParserFactory:
    """Factory that creates parsers from string identifiers."""

    def __init__(self) -> None:
        self._registry: Dict[str, Type] = {}

    def register(self, name: str) -> Callable:
        """Decorator to register a parser class."""
        def decorator(cls: Type) -> Type:
            self._registry[name] = cls
            return cls
        return decorator

    def create(self, name: str, **kwargs: Any) -> Any:
        """Create a parser by name. Raises ValueError if unknown."""
        cls = self._registry.get(name)
        if cls is None:
            available = ", ".join(sorted(self._registry.keys()))
            raise ValueError(
                f"Unknown parser: '{name}'. Available: {available}"
            )
        return cls(**kwargs)

    def list_parsers(self) -> List[str]:
        """Return sorted list of registered parser names."""
        return sorted(self._registry.keys())

    def get_by_extension(self, ext: str) -> Optional[Any]:
        """Find parser that handles the given file extension."""
        if not ext.startswith("."):
            ext = f".{ext}"
        for cls in self._registry.values():
            instance = cls()
            if ext in instance.file_extensions:
                return instance
        return None


# Create factory instance
factory = ParserFactory()


@factory.register("json")
class JsonParser:
    @property
    def name(self) -> str:
        return "json"

    @property
    def file_extensions(self) -> List[str]:
        return [".json"]

    def parse(self, raw: str) -> Any:
        return json.loads(raw)


@factory.register("csv")
class CsvParser:
    def __init__(self, delimiter: str = ",") -> None:
        self._delimiter = delimiter

    @property
    def name(self) -> str:
        return "csv"

    @property
    def file_extensions(self) -> List[str]:
        return [".csv"]

    def parse(self, raw: str) -> List[Dict[str, str]]:
        lines = raw.strip().split("\n")
        if not lines:
            return []
        headers = [h.strip() for h in lines[0].split(self._delimiter)]
        rows = []
        for line in lines[1:]:
            values = [v.strip() for v in line.split(self._delimiter)]
            rows.append(dict(zip(headers, values)))
        return rows


@factory.register("toml")
class TomlParser:
    @property
    def name(self) -> str:
        return "toml"

    @property
    def file_extensions(self) -> List[str]:
        return [".toml", ".ini"]

    def parse(self, raw: str) -> Dict[str, str]:
        result: Dict[str, str] = {}
        for line in raw.strip().split("\n"):
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("["):
                continue
            if "=" in line:
                key, value = line.split("=", 1)
                result[key.strip()] = value.strip().strip('"').strip("'")
        return result


@factory.register("yaml")
class YamlParser:
    @property
    def name(self) -> str:
        return "yaml"

    @property
    def file_extensions(self) -> List[str]:
        return [".yaml", ".yml"]

    def parse(self, raw: str) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for line in raw.strip().split("\n"):
            if not line.strip() or line.strip().startswith("#"):
                continue
            if ":" in line:
                key, value = line.split(":", 1)
                value = value.strip()
                # Simple type coercion
                if value.lower() in ("true", "yes"):
                    result[key.strip()] = True
                elif value.lower() in ("false", "no"):
                    result[key.strip()] = False
                elif value.isdigit():
                    result[key.strip()] = int(value)
                else:
                    result[key.strip()] = value
        return result


# Usage examples
if __name__ == "__main__":
    print("=== Available Parsers ===")
    print(factory.list_parsers())

    # JSON
    jp = factory.create("json")
    print(f"\nJSON: {jp.parse('{\"name\": \"Alice\", \"age\": 30}')}")

    # CSV
    cp = factory.create("csv")
    csv_data = "name,age,email\nAlice,30,alice@test.com\nBob,25,bob@test.com"
    print(f"CSV: {cp.parse(csv_data)}")

    # TOML
    tp = factory.create("toml")
    toml_data = 'host = "localhost"\nport = 8080\ndebug = true'
    print(f"TOML: {tp.parse(toml_data)}")

    # YAML
    yp = factory.create("yaml")
    yaml_data = "name: Alice\nage: 30\nactive: true"
    print(f"YAML: {yp.parse(yaml_data)}")

    # By extension
    parser = factory.get_by_extension(".yml")
    print(f"\nParser for .yml: {parser.name if parser else 'not found'}")

    # Protocol check
    print(f"\nJsonParser satisfies Parser protocol: {isinstance(jp, Parser)}")

    # Unknown parser
    try:
        factory.create("xml")
    except ValueError as e:
        print(f"\nError: {e}")
```

## Exercise 2 Solution: Strategy Pattern

```python
from typing import Protocol, List, TypeVar, Callable, Optional
import time
import random


T = TypeVar("T")


class SortStrategy(Protocol):
    """Protocol for sorting strategies."""

    @property
    def name(self) -> str: ...

    def sort(self, items: List[int]) -> List[int]: ...


class BubbleSort:
    """O(n^2) bubble sort."""

    @property
    def name(self) -> str:
        return "BubbleSort"

    def sort(self, items: List[int]) -> List[int]:
        arr = list(items)
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
        return arr


class InsertionSort:
    """O(n^2) insertion sort."""

    @property
    def name(self) -> str:
        return "InsertionSort"

    def sort(self, items: List[int]) -> List[int]:
        arr = list(items)
        for i in range(1, len(arr)):
            key = arr[i]
            j = i - 1
            while j >= 0 and arr[j] > key:
                arr[j + 1] = arr[j]
                j -= 1
            arr[j + 1] = key
        return arr


class MergeSort:
    """O(n log n) merge sort."""

    @property
    def name(self) -> str:
        return "MergeSort"

    def sort(self, items: List[int]) -> List[int]:
        if len(items) <= 1:
            return list(items)
        mid = len(items) // 2
        left = self.sort(items[:mid])
        right = self.sort(items[mid:])
        return self._merge(left, right)

    def _merge(self, left: List[int], right: List[int]) -> List[int]:
        result: List[int] = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result


class QuickSort:
    """O(n log n) quicksort with middle pivot."""

    @property
    def name(self) -> str:
        return "QuickSort"

    def sort(self, items: List[int]) -> List[int]:
        if len(items) <= 1:
            return list(items)
        pivot = items[len(items) // 2]
        left = [x for x in items if x < pivot]
        middle = [x for x in items if x == pivot]
        right = [x for x in items if x > pivot]
        return self.sort(left) + middle + self.sort(right)


class Sorter:
    """Sorts items using a pluggable strategy."""

    def __init__(self, strategy: SortStrategy) -> None:
        self._strategy = strategy

    def sort(self, items: List[int]) -> List[int]:
        return self._strategy.sort(items)

    def set_strategy(self, strategy: SortStrategy) -> None:
        self._strategy = strategy

    @property
    def strategy_name(self) -> str:
        return self._strategy.name

    def benchmark(self, items: List[int], runs: int = 3) -> float:
        """Run sort multiple times and return average duration in seconds."""
        total = 0.0
        for _ in range(runs):
            start = time.perf_counter()
            self._strategy.sort(items)
            total += time.perf_counter() - start
        return total / runs


class AutoSorter:
    """Automatically selects the best strategy based on input size."""

    def __init__(self) -> None:
        self._insertion = InsertionSort()
        self._quick = QuickSort()
        self._merge = MergeSort()

    def sort(self, items: List[int]) -> List[int]:
        strategy = self._pick_strategy(len(items))
        return strategy.sort(items)

    def _pick_strategy(self, size: int) -> SortStrategy:
        if size < 20:
            return self._insertion
        elif size < 1000:
            return self._quick
        else:
            return self._merge

    def strategy_for(self, size: int) -> str:
        """Return the name of the strategy that would be chosen."""
        return self._pick_strategy(size).name


# Usage examples
if __name__ == "__main__":
    test_data = [5, 3, 8, 1, 9, 2, 7, 4, 6, 0]
    expected = sorted(test_data)

    strategies: List[SortStrategy] = [
        BubbleSort(), InsertionSort(), MergeSort(), QuickSort()
    ]

    # Verify correctness
    print("=== Correctness Check ===")
    for s in strategies:
        result = s.sort(test_data)
        status = "PASS" if result == expected else "FAIL"
        print(f"  {s.name:15s}: {status} -> {result}")

    # Runtime strategy swap
    print("\n=== Strategy Swap ===")
    sorter = Sorter(BubbleSort())
    print(f"  Using: {sorter.strategy_name}")
    sorter.set_strategy(QuickSort())
    print(f"  Swapped to: {sorter.strategy_name}")
    print(f"  Result: {sorter.sort(test_data)}")

    # Benchmark
    print("\n=== Benchmark ===")
    for size in [100, 1000, 5000]:
        data = [random.randint(0, 10000) for _ in range(size)]
        print(f"\n  Size: {size}")
        for s in strategies:
            sorter = Sorter(s)
            avg_time = sorter.benchmark(data, runs=3)
            print(f"    {s.name:15s}: {avg_time*1000:.2f}ms")

    # AutoSorter
    print("\n=== AutoSorter ===")
    auto = AutoSorter()
    for size in [10, 100, 5000]:
        print(f"  Size {size:5d}: uses {auto.strategy_for(size)}")
    result = auto.sort(test_data)
    print(f"  AutoSort result: {result}")
```

## Exercise 3 Solution: Observer Pattern, Async Event System

```python
import asyncio
from typing import Dict, List, Callable, Any, Type
from dataclasses import dataclass, field
from datetime import datetime, timezone


# --- Typed Events ---

@dataclass
class Event:
    """Base event class."""
    timestamp: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )


@dataclass
class UserCreated(Event):
    user_id: int = 0
    username: str = ""
    email: str = ""


@dataclass
class OrderPlaced(Event):
    order_id: str = ""
    user_id: int = 0
    total: float = 0.0
    items: List[str] = field(default_factory=list)


@dataclass
class PaymentProcessed(Event):
    order_id: str = ""
    amount: float = 0.0
    success: bool = False


# --- Async Event Bus ---

class AsyncEventBus:
    """Event bus with typed events and async handlers."""

    def __init__(self) -> None:
        self._handlers: Dict[Type[Event], List[Callable]] = {}

    def on(self, event_type: Type[Event]) -> Callable:
        """Decorator to register a handler for an event type."""
        def decorator(fn: Callable) -> Callable:
            if event_type not in self._handlers:
                self._handlers[event_type] = []
            self._handlers[event_type].append(fn)
            return fn
        return decorator

    async def emit(self, event: Event) -> List[Any]:
        """Dispatch event to all registered handlers concurrently."""
        handlers = self._handlers.get(type(event), [])
        if not handlers:
            return []
        results = await asyncio.gather(
            *[handler(event) for handler in handlers],
            return_exceptions=True,
        )
        return list(results)

    def handlers_for(self, event_type: Type[Event]) -> List[Callable]:
        """Return handlers registered for this event type."""
        return list(self._handlers.get(event_type, []))

    def clear(self) -> None:
        """Remove all handlers."""
        self._handlers.clear()


# --- Create bus and register handlers ---

bus = AsyncEventBus()


@bus.on(UserCreated)
async def welcome_email(event: UserCreated) -> str:
    """Send welcome email to new user."""
    await asyncio.sleep(0.1)  # simulate async work
    msg = f"Welcome email sent to {event.email}"
    print(f"  [welcome_email] {msg}")
    return msg


@bus.on(UserCreated)
async def init_profile(event: UserCreated) -> str:
    """Initialize user profile."""
    await asyncio.sleep(0.05)
    msg = f"Profile initialized for {event.username}"
    print(f"  [init_profile] {msg}")
    return msg


@bus.on(OrderPlaced)
async def validate_order(event: OrderPlaced) -> str:
    """Validate the order details."""
    await asyncio.sleep(0.05)
    msg = f"Order {event.order_id} validated (${event.total:.2f})"
    print(f"  [validate_order] {msg}")
    return msg


@bus.on(OrderPlaced)
async def reserve_inventory(event: OrderPlaced) -> str:
    """Reserve inventory for the order."""
    await asyncio.sleep(0.1)
    msg = f"Inventory reserved for {len(event.items)} items"
    print(f"  [reserve_inventory] {msg}")
    return msg


@bus.on(PaymentProcessed)
async def update_order_status(event: PaymentProcessed) -> str:
    """Update order status after payment."""
    await asyncio.sleep(0.05)
    status = "confirmed" if event.success else "payment_failed"
    msg = f"Order {event.order_id} status: {status}"
    print(f"  [update_order_status] {msg}")
    return msg


# Handler that subscribes to multiple event types
@bus.on(UserCreated)
@bus.on(OrderPlaced)
@bus.on(PaymentProcessed)
async def audit_log(event: Event) -> str:
    """Log all events to audit trail (subscribed to multiple types)."""
    await asyncio.sleep(0.01)
    msg = f"AUDIT: {type(event).__name__} at {event.timestamp}"
    print(f"  [audit_log] {msg}")
    return msg


# --- Workflow ---

async def main() -> None:
    print("=== Event-Driven Workflow ===\n")

    # Step 1: User created
    print("Step 1: UserCreated")
    user_event = UserCreated(user_id=1, username="alice", email="alice@example.com")
    results = await bus.emit(user_event)
    print(f"  -> {len(results)} handlers fired\n")

    # Step 2: Order placed
    print("Step 2: OrderPlaced")
    order_event = OrderPlaced(
        order_id="ORD-001", user_id=1, total=99.99,
        items=["widget", "gadget"]
    )
    results = await bus.emit(order_event)
    print(f"  -> {len(results)} handlers fired\n")

    # Step 3: Payment processed
    print("Step 3: PaymentProcessed")
    payment_event = PaymentProcessed(
        order_id="ORD-001", amount=99.99, success=True
    )
    results = await bus.emit(payment_event)
    print(f"  -> {len(results)} handlers fired\n")

    # Show handler counts
    print("=== Handler Summary ===")
    for event_type in [UserCreated, OrderPlaced, PaymentProcessed]:
        handlers = bus.handlers_for(event_type)
        print(f"  {event_type.__name__}: {len(handlers)} handlers")


if __name__ == "__main__":
    asyncio.run(main())
```

## Exercise 4 Solution: Typed Decorator, Runtime Type Validation

```python
import asyncio
import functools
from typing import (
    get_type_hints, Any, Callable, Dict, List, Optional, Union,
    Tuple,
)
import inspect


def _check_value(value: Any, expected: Any, param_name: str) -> None:
    """Check that a value matches the expected type annotation."""
    if expected is inspect.Parameter.empty or expected is Any:
        return

    origin = getattr(expected, "__origin__", None)
    args = getattr(expected, "__args__", ())

    # Union / Optional
    if origin is Union:
        for arg in args:
            try:
                _check_value(value, arg, param_name)
                return
            except TypeError:
                pass
        raise TypeError(
            f"Argument '{param_name}' expected {expected}, "
            f"got {type(value).__name__}: {value!r}"
        )

    # None type
    if expected is type(None):
        if value is not None:
            raise TypeError(
                f"Argument '{param_name}' expected None, "
                f"got {type(value).__name__}: {value!r}"
            )
        return

    # List[X]
    if origin is list:
        if not isinstance(value, list):
            raise TypeError(
                f"Argument '{param_name}' expected list, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args:
            for i, item in enumerate(value):
                _check_value(item, args[0], f"{param_name}[{i}]")
        return

    # Dict[K, V]
    if origin is dict:
        if not isinstance(value, dict):
            raise TypeError(
                f"Argument '{param_name}' expected dict, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args and len(args) == 2:
            for k, v in value.items():
                _check_value(k, args[0], f"{param_name}.key")
                _check_value(v, args[1], f"{param_name}[{k!r}]")
        return

    # Tuple[X, ...]
    if origin is tuple:
        if not isinstance(value, tuple):
            raise TypeError(
                f"Argument '{param_name}' expected tuple, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args:
            for i, (item, item_type) in enumerate(zip(value, args)):
                _check_value(item, item_type, f"{param_name}[{i}]")
        return

    # Basic types
    if isinstance(expected, type):
        if not isinstance(value, expected):
            raise TypeError(
                f"Argument '{param_name}' expected {expected.__name__}, "
                f"got {type(value).__name__}: {value!r}"
            )


def check_types(fn: Callable) -> Callable:
    """Decorator that validates function arguments match their type hints."""
    hints = get_type_hints(fn)
    sig = inspect.signature(fn)

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        # Bind arguments to parameter names
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()

        # Check each argument
        for param_name, value in bound.arguments.items():
            if param_name in hints:
                _check_value(value, hints[param_name], param_name)

        # Call the function
        result = fn(*args, **kwargs)

        # Check return type
        if "return" in hints:
            _check_value(result, hints["return"], "return")

        return result

    return wrapper


def check_types_async(fn: Callable) -> Callable:
    """Decorator that validates async function arguments match their type hints."""
    hints = get_type_hints(fn)
    sig = inspect.signature(fn)

    @functools.wraps(fn)
    async def wrapper(*args: Any, **kwargs: Any) -> Any:
        # Bind arguments to parameter names
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()

        # Check each argument
        for param_name, value in bound.arguments.items():
            if param_name in hints:
                _check_value(value, hints[param_name], param_name)

        # Call the function
        result = await fn(*args, **kwargs)

        # Check return type
        if "return" in hints:
            _check_value(result, hints["return"], "return")

        return result

    return wrapper


# --- Apply to functions ---

@check_types
def greet(name: str, excited: bool = False) -> str:
    return f"Hello, {name}{'!' if excited else '.'}"


@check_types
def add_items(cart: List[str], item: str) -> List[str]:
    return cart + [item]


@check_types
def lookup(data: Dict[str, int], key: str) -> Optional[int]:
    return data.get(key)


@check_types
def process(value: Union[int, str]) -> str:
    return str(value)


@check_types_async
async def fetch_user(
    user_id: int, fields: Optional[List[str]] = None
) -> Dict[str, Any]:
    return {"id": user_id, "name": "Alice"}


# Usage examples
if __name__ == "__main__":
    # Valid calls
    print("=== Valid Calls ===")
    print(greet("Alice"))                         # Hello, Alice.
    print(greet("Bob", excited=True))             # Hello, Bob!
    print(add_items(["apple"], "banana"))          # ['apple', 'banana']
    print(lookup({"a": 1, "b": 2}, "a"))          # 1
    print(lookup({"a": 1}, "z"))                   # None (Optional allows it)
    print(process(42))                             # "42"
    print(process("hello"))                        # "hello"

    # Invalid calls
    print("\n=== Invalid Calls ===")

    try:
        greet(42)  # name should be str
    except TypeError as e:
        print(f"Caught: {e}")

    try:
        add_items("not a list", "item")  # cart should be List[str]
    except TypeError as e:
        print(f"Caught: {e}")

    try:
        add_items([1, 2, 3], "item")  # list elements should be str
    except TypeError as e:
        print(f"Caught: {e}")

    try:
        lookup({"a": "not_int"}, "a")  # dict values should be int
    except TypeError as e:
        print(f"Caught: {e}")

    try:
        process(3.14)  # not int or str
    except TypeError as e:
        print(f"Caught: {e}")

    # Async
    print("\n=== Async ===")

    async def test_async() -> None:
        result = await fetch_user(1, fields=["name", "email"])
        print(f"fetch_user: {result}")

        try:
            await fetch_user("not_int")
        except TypeError as e:
            print(f"Caught: {e}")

    asyncio.run(test_async())
```

## Exercise 5 Solution: Error Architecture

```python
import asyncio
from typing import Optional, Any, Dict


# ============================================================================
# Transport Layer Exceptions
# ============================================================================

class TransportError(Exception):
    """Base exception for transport layer errors."""

    def __init__(
        self, message: str, url: str = "", status_code: int = 0
    ) -> None:
        super().__init__(message)
        self.url = url
        self.status_code = status_code


class ConnectionRefusedError_(TransportError):
    """Connection was refused by the server."""
    pass


class RequestTimeoutError(TransportError):
    """Request timed out."""
    pass


class RateLimitError(TransportError):
    """Rate limit exceeded."""

    def __init__(
        self, message: str, url: str = "", retry_after: float = 0.0
    ) -> None:
        super().__init__(message, url=url, status_code=429)
        self.retry_after = retry_after


# ============================================================================
# Business Layer Exceptions
# ============================================================================

class BusinessError(Exception):
    """Base exception for business layer errors."""

    def __init__(
        self, message: str, error_code: str = "", details: Optional[Dict[str, Any]] = None
    ) -> None:
        super().__init__(message)
        self.error_code = error_code
        self.details = details or {}


class ValidationError(BusinessError):
    """Input validation failed."""

    def __init__(
        self, field_name: str, constraint: str, value: Any
    ) -> None:
        super().__init__(
            f"Validation failed for '{field_name}': {constraint}",
            error_code="VALIDATION_ERROR",
            details={"field": field_name, "constraint": constraint, "value": value},
        )
        self.field_name = field_name
        self.constraint = constraint
        self.value = value


class NotFoundError(BusinessError):
    """Requested resource was not found."""

    def __init__(self, resource_type: str, resource_id: Any) -> None:
        super().__init__(
            f"{resource_type} with id '{resource_id}' not found",
            error_code="NOT_FOUND",
            details={"resource_type": resource_type, "resource_id": resource_id},
        )
        self.resource_type = resource_type
        self.resource_id = resource_id


class ConflictError(BusinessError):
    """Operation conflicts with existing state."""

    def __init__(self, existing_id: Any, attempted_action: str) -> None:
        super().__init__(
            f"Conflict: cannot {attempted_action} (existing: {existing_id})",
            error_code="CONFLICT",
            details={"existing_id": existing_id, "action": attempted_action},
        )
        self.existing_id = existing_id
        self.attempted_action = attempted_action


# ============================================================================
# Presentation Layer Exceptions
# ============================================================================

class PresentationError(Exception):
    """Base exception for presentation layer errors."""

    def __init__(
        self, status_code: int, user_message: str, internal_message: str = ""
    ) -> None:
        super().__init__(user_message)
        self.status_code = status_code
        self.user_message = user_message
        self.internal_message = internal_message or user_message


class BadRequestError(PresentationError):
    def __init__(self, user_message: str, internal_message: str = "") -> None:
        super().__init__(400, user_message, internal_message)


class NotFoundResponseError(PresentationError):
    def __init__(self, user_message: str, internal_message: str = "") -> None:
        super().__init__(404, user_message, internal_message)


class InternalServerError(PresentationError):
    def __init__(self, user_message: str, internal_message: str = "") -> None:
        super().__init__(500, user_message, internal_message)


# ============================================================================
# Layer Functions
# ============================================================================

# Simulated data store
USERS = {1: {"id": 1, "name": "Alice", "email": "alice@example.com"}}


async def http_get(url: str) -> dict:
    """Transport layer: simulate HTTP GET."""
    await asyncio.sleep(0.05)

    if "timeout" in url:
        raise RequestTimeoutError(f"GET {url} timed out after 30s", url=url)

    if "rate-limit" in url:
        raise RateLimitError(f"Rate limit exceeded for {url}", url=url, retry_after=60.0)

    if "refuse" in url:
        raise ConnectionRefusedError_(f"Connection refused: {url}", url=url)

    # Simulate successful response
    parts = url.rstrip("/").split("/")
    resource_id = int(parts[-1]) if parts[-1].isdigit() else 0

    if resource_id in USERS:
        return {"status": 200, "body": USERS[resource_id]}
    else:
        raise TransportError(f"GET {url} returned 404", url=url, status_code=404)


async def get_user(user_id: int) -> dict:
    """Business layer: fetch a user, wrapping transport errors."""
    if user_id <= 0:
        raise ValidationError("user_id", "must be positive", user_id)

    url = f"/api/users/{user_id}"
    try:
        response = await http_get(url)
        return response["body"]
    except TransportError as e:
        if e.status_code == 404:
            raise NotFoundError("User", user_id) from e
        raise BusinessError(
            f"Failed to fetch user {user_id}",
            error_code="FETCH_FAILED",
            details={"user_id": user_id, "url": url},
        ) from e


async def handle_get_user(user_id: int) -> dict:
    """Presentation layer: HTTP handler wrapping business errors."""
    try:
        user = await get_user(user_id)
        return {"status": 200, "body": user}
    except ValidationError as e:
        raise BadRequestError(
            f"Invalid request: {e}",
            internal_message=str(e),
        ) from e
    except NotFoundError as e:
        raise NotFoundResponseError(
            f"User not found",
            internal_message=str(e),
        ) from e
    except BusinessError as e:
        raise InternalServerError(
            "An internal error occurred",
            internal_message=str(e),
        ) from e


# ============================================================================
# Error Chain Report
# ============================================================================

def error_chain_report(error: Exception) -> str:
    """Walk the __cause__ chain and produce a readable report."""
    lines = []
    current: Optional[BaseException] = error
    depth = 0

    while current is not None:
        prefix = "  " * depth
        arrow = "caused by " if depth > 0 else ""
        type_name = type(current).__name__
        lines.append(f"{prefix}{arrow}{type_name}: {current}")
        current = current.__cause__
        depth += 1

    return "\n".join(lines)


# ============================================================================
# Main
# ============================================================================

async def main() -> None:
    # Scenario 1: Successful request
    print("=== Scenario 1: Success ===")
    try:
        result = await handle_get_user(1)
        print(f"  Response: {result}")
    except PresentationError as e:
        print(f"  Error: {e}")

    # Scenario 2: User not found (transport 404 -> business NotFound -> presentation 404)
    print("\n=== Scenario 2: Not Found (chained) ===")
    try:
        await handle_get_user(999)
    except PresentationError as e:
        print(f"  HTTP {e.status_code}: {e.user_message}")
        print(f"\n  Error chain:")
        print(f"  {error_chain_report(e)}")

    # Scenario 3: Validation error (business -> presentation 400)
    print("\n=== Scenario 3: Validation Error ===")
    try:
        await handle_get_user(-1)
    except PresentationError as e:
        print(f"  HTTP {e.status_code}: {e.user_message}")
        print(f"\n  Error chain:")
        print(f"  {error_chain_report(e)}")

    # Scenario 4: Direct transport error check
    print("\n=== Scenario 4: Transport Timeout ===")
    try:
        await http_get("/api/users/timeout")
    except TransportError as e:
        print(f"  Transport error: {e}")
        print(f"  URL: {e.url}")

    # Scenario 5: Rate limit
    print("\n=== Scenario 5: Rate Limit ===")
    try:
        await http_get("/api/rate-limit")
    except RateLimitError as e:
        print(f"  Rate limited: {e}")
        print(f"  Retry after: {e.retry_after}s")


if __name__ == "__main__":
    asyncio.run(main())
