class TestSortStrategies:
    """Tests for sorting strategies."""

    def _bubble_sort(self, items: List[int]) -> List[int]:
        arr = list(items)
        n = len(arr)
        for i in range(n):
            for j in range(n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
        return arr

    def _quick_sort(self, items: List[int]) -> List[int]:
        if len(items) <= 1:
            return list(items)
        pivot = items[len(items) // 2]
        left = [x for x in items if x < pivot]
        mid = [x for x in items if x == pivot]
        right = [x for x in items if x > pivot]
        return self._quick_sort(left) + mid + self._quick_sort(right)

    def test_sorts_correctly(self) -> None:
        data = [5, 3, 8, 1, 9, 2]
        assert self._bubble_sort(data) == [1, 2, 3, 5, 8, 9]
        assert self._quick_sort(data) == [1, 2, 3, 5, 8, 9]

    def test_empty_list(self) -> None:
        assert self._bubble_sort([]) == []
        assert self._quick_sort([]) == []

    def test_single_element(self) -> None:
        assert self._bubble_sort([42]) == [42]
        assert self._quick_sort([42]) == [42]

    def test_already_sorted(self) -> None:
        data = [1, 2, 3, 4, 5]
        assert self._bubble_sort(data) == data
        assert self._quick_sort(data) == data

    def test_reverse_sorted(self) -> None:
        data = [5, 4, 3, 2, 1]
        assert self._bubble_sort(data) == [1, 2, 3, 4, 5]

    def test_duplicates(self) -> None:
        data = [3, 1, 3, 1, 2]
        assert self._quick_sort(data) == [1, 1, 2, 3, 3]


