class TestCheckTypes:
    """Tests for the @check_types decorator."""

    def _check_types(self, fn: Callable) -> Callable:
        """Minimal check_types for self-contained test."""
        import functools
        import inspect
        from typing import get_type_hints, Union

        hints = get_type_hints(fn)
        sig = inspect.signature(fn)

        @functools.wraps(fn)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()
            for name, val in bound.arguments.items():
                if name in hints:
                    exp = hints[name]
                    origin = getattr(exp, "__origin__", None)
                    t_args = getattr(exp, "__args__", ())
                    if origin is Union:
                        if not any(isinstance(val, a) if isinstance(a, type) else val is None and a is type(None) for a in t_args):
                            raise TypeError(f"Argument '{name}' type mismatch")
                    elif isinstance(exp, type) and not isinstance(val, exp):
                        raise TypeError(
                            f"Argument '{name}' expected {exp.__name__}, "
                            f"got {type(val).__name__}: {val!r}"
                        )
            return fn(*args, **kwargs)
        return wrapper

