            depth = 0
            while current is not None:
                prefix = "  " * depth
                lines.append(f"{prefix}{type(current).__name__}: {current}")
                current = current.__cause__
                depth += 1
            return "\n".join(lines)

        try:
            try:
                raise A("root cause")
            except A as e:
                raise B("wrapped") from e
        except B as e:
            report = chain_report(e)
            assert "B: wrapped" in report
            assert "A: root cause" in report

