"""
Task Automation Framework (Capstone)
=====================================
Integrates all concepts from Weeks 1-6:
- Functions, closures, decorators (Week 1-3)
- Type hints, generics, protocols, validation (Week 4)
- Async/await, concurrency, timeouts, retries (Week 5)
- Factory, Strategy, Observer, exceptions, testing (Week 6)
"""

from __future__ import annotations

import asyncio
import functools
import json
import os
import sys
import time
from collections import defaultdict
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from enum import Enum
from typing import (
    Any, Callable, Coroutine, Dict, Generic, List, Optional,
    Protocol, Set, Tuple, Type, TypeVar, Union, get_type_hints,
)


# ============================================================================
# Runtime Type Validation (@validate from Week 4)
# ============================================================================

def _check_type(value: Any, expected: Any, name: str) -> None:
    """Validate value matches expected type annotation."""
    if expected is type(None):
        if value is not None:
            raise TypeError(f"Field '{name}' expected None, got {type(value).__name__}: {value!r}")
        return
    origin = getattr(expected, "__origin__", None)
    args = getattr(expected, "__args__", ())
    if origin is Union:
        for arg in args:
            try:
                _check_type(value, arg, name)
                return
            except TypeError:
                pass
        raise TypeError(f"Field '{name}' expected {expected}, got {type(value).__name__}: {value!r}")
    if origin is list:
        if not isinstance(value, list):
            raise TypeError(f"Field '{name}' expected list, got {type(value).__name__}: {value!r}")
        if args:
            for i, item in enumerate(value):
                _check_type(item, args[0], f"{name}[{i}]")
        return
    if origin is dict:
        if not isinstance(value, dict):
            raise TypeError(f"Field '{name}' expected dict, got {type(value).__name__}: {value!r}")
        if args and len(args) == 2:
            for k, v in value.items():
                _check_type(k, args[0], f"{name}.key")
                _check_type(v, args[1], f"{name}[{k!r}]")
        return
    if isinstance(expected, type) and not isinstance(value, expected):
        raise TypeError(f"Field '{name}' expected {expected.__name__}, got {type(value).__name__}: {value!r}")


def validate(cls: type) -> type:
    """Decorator: runtime type validation on dataclass __init__."""
    original_init = cls.__init__
    hints = get_type_hints(cls)

    @functools.wraps(original_init)
    def checked_init(self: Any, *args: Any, **kwargs: Any) -> None:
        original_init(self, *args, **kwargs)
        for fname, ftype in hints.items():
            if not hasattr(self, fname):
                continue
            val = getattr(self, fname)
            if val is None:
                origin = getattr(ftype, "__origin__", None)
                fargs = getattr(ftype, "__args__", ())
                if not (origin is Union and type(None) in fargs):
                    raise TypeError(f"Field '{fname}' is not Optional but got None")
            else:
                _check_type(val, ftype, fname)

    cls.__init__ = checked_init
    return cls


