@validate
@dataclass
class RunnerConfig:
    max_workers: int = 5
    global_timeout: float = 300.0
    retry_delay_base: float = 1.0
    retry_delay_max: float = 30.0
    log_level: str = "INFO"
    log_format: str = "json"

    @classmethod
    def from_env(cls, prefix: str = "RUNNER") -> RunnerConfig:
        """Load from environment variables with type coercion."""
        def _get(key: str, default: str, cast: type) -> Any:
            raw = os.environ.get(f"{prefix}_{key}", default)
            if cast is bool:
                return raw.lower() in ("true", "1", "yes")
            return cast(raw)

        return cls(
            max_workers=_get("MAX_WORKERS", "5", int),
            global_timeout=_get("GLOBAL_TIMEOUT", "300.0", float),
            retry_delay_base=_get("RETRY_DELAY_BASE", "1.0", float),
            retry_delay_max=_get("RETRY_DELAY_MAX", "30.0", float),
            log_level=_get("LOG_LEVEL", "INFO", str),
            log_format=_get("LOG_FORMAT", "json", str),
        )


