# Task Status and Result
# ============================================================================

class TaskStatus(Enum):
    PENDING = "pending"
    RUNNING = "running"
    SUCCESS = "success"
    FAILED = "failed"
    TIMEOUT = "timeout"
    SKIPPED = "skipped"


@dataclass
class TaskResult:
    name: str
    status: TaskStatus
    result: Any = None
    error: str = ""
    attempts: int = 0
    duration: float = 0.0


# ============================================================================
# Task Metadata and Registry (Week 3: decorators)
# ============================================================================

@dataclass
class TaskMeta:
    name: str
    fn: Callable[..., Coroutine[Any, Any, Any]]
    timeout: float
    retries: int
    depends_on: List[str]


_TASK_REGISTRY: Dict[str, TaskMeta] = {}


def task(
    name: str,
    timeout: float = 30.0,
    retries: int = 1,
    depends_on: Optional[List[str]] = None,
) -> Callable:
    """Decorator to register an async function as a task."""
    def decorator(fn: Callable[..., Coroutine[Any, Any, Any]]) -> Callable:
        meta = TaskMeta(
            name=name,
            fn=fn,
            timeout=timeout,
            retries=retries,
            depends_on=depends_on or [],
        )
        _TASK_REGISTRY[name] = meta

        @functools.wraps(fn)
        async def wrapper(*args: Any, **kwargs: Any) -> Any:
            return await fn(*args, **kwargs)

        wrapper._task_meta = meta  # type: ignore
        return wrapper

    return decorator


