@dataclass
class TaskEvent:
    timestamp: str
    event_type: str
    task_name: str
    attempt: int = 0
    duration: float = 0.0
    error: str = ""
    details: Optional[Dict[str, Any]] = None


class EventBus:
    """Async event bus with typed event support."""

    def __init__(self) -> None:
        self._handlers: Dict[type, List[Callable]] = {}

    def on(self, event_type: type) -> Callable:
        def decorator(fn: Callable) -> Callable:
            self._handlers.setdefault(event_type, []).append(fn)
            return fn
        return decorator

    async def emit(self, event: Any) -> None:
        handlers = self._handlers.get(type(event), [])
        if handlers:
            await asyncio.gather(*[h(event) for h in handlers], return_exceptions=True)


# ============================================================================
# Plugin System (Week 6: Factory + Protocol)
# ============================================================================

class TaskPlugin(Protocol):
    """Protocol for task plugins."""
    name: str
    async def before_task(self, task_name: str) -> None: ...
    async def after_task(self, task_name: str, result: Any) -> None: ...
    async def on_error(self, task_name: str, error: Exception) -> None: ...


_PLUGIN_REGISTRY: Dict[str, Type] = {}


def register_plugin(cls: Type) -> Type:
    """Decorator to register a plugin class."""
    _PLUGIN_REGISTRY[cls.name] = cls
    return cls


@register_plugin
class TimingPlugin:
    """Tracks execution timing for each task."""
    name = "timing"

    def __init__(self) -> None:
        self.timings: Dict[str, float] = {}
        self.task_count = 0

    async def before_task(self, task_name: str) -> None:
        self.timings[task_name] = time.perf_counter()

    async def after_task(self, task_name: str, result: Any) -> None:
        start = self.timings.get(task_name, time.perf_counter())
        self.timings[task_name] = time.perf_counter() - start
        self.task_count += 1

    async def on_error(self, task_name: str, error: Exception) -> None:
        start = self.timings.get(task_name, time.perf_counter())
        self.timings[task_name] = time.perf_counter() - start
        self.task_count += 1

    def summary(self) -> str:
        if not self.timings:
            return "No tasks tracked"
        avg = sum(self.timings.values()) / len(self.timings)
        return f"{self.task_count} tasks tracked, avg {avg:.2f}s"


@register_plugin
class AuditPlugin:
    """Records all task events to an audit log."""
    name = "audit"

    def __init__(self) -> None:
        self.events: List[Dict[str, Any]] = []

    async def before_task(self, task_name: str) -> None:
        self.events.append({
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "task": task_name,
            "action": "started",
        })

    async def after_task(self, task_name: str, result: Any) -> None:
        self.events.append({
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "task": task_name,
            "action": "completed",
        })

    async def on_error(self, task_name: str, error: Exception) -> None:
        self.events.append({
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "task": task_name,
            "action": "error",
            "error": str(error),
        })

    def summary(self) -> str:
        return f"{len(self.events)} events recorded"


# ============================================================================
# Task Runner (Weeks 4-6: generics, async, patterns)
# ============================================================================

class TaskRunner:
    """Runs registered tasks with dependency resolution, concurrency, retries."""

    def __init__(self, config: Optional[RunnerConfig] = None) -> None:
        self._config = config or RunnerConfig()
        self._tasks: Dict[str, TaskMeta] = {}
        self._results: Dict[str, TaskResult] = {}
        self._bus = EventBus()
        self._plugins: List[Any] = []

        # Register default event handler
        @self._bus.on(TaskEvent)
        async def _log_event(event: TaskEvent) -> None:
            entry = {
                "timestamp": event.timestamp,
                "event": event.event_type,
                "task": event.task_name,
            }
            if event.attempt:
                entry["attempt"] = event.attempt
            if event.duration:
                entry["duration"] = round(event.duration, 3)
            if event.error:
                entry["error"] = event.error
            if event.details:
                entry.update(event.details)
            print(json.dumps(entry))

    def register(self, task_fn: Callable) -> None:
        """Register a task function."""
        meta: Optional[TaskMeta] = getattr(task_fn, "_task_meta", None)
        if meta is None:
            raise TaskRegistrationError(f"{task_fn} is not a registered task")
        self._tasks[meta.name] = meta

    def register_all(self) -> None:
        """Register all tasks from the global registry."""
        for name, meta in _TASK_REGISTRY.items():
            self._tasks[name] = meta

    def add_plugin(self, plugin: Any) -> None:
        """Add a plugin instance."""
        self._plugins.append(plugin)

    def add_all_plugins(self) -> None:
        """Instantiate and add all registered plugins."""
        for name, cls in _PLUGIN_REGISTRY.items():
            self._plugins.append(cls())

    def get_execution_order(self) -> List[List[str]]:
        """Topological sort into concurrent layers. Detects cycles."""
        in_degree: Dict[str, int] = {name: 0 for name in self._tasks}
        dependents: Dict[str, List[str]] = defaultdict(list)

        for name, meta in self._tasks.items():
            for dep in meta.depends_on:
                if dep not in self._tasks:
                    raise TaskRegistrationError(
                        f"Task '{name}' depends on unknown task '{dep}'"
                    )
                dependents[dep].append(name)
                in_degree[name] += 1

        layers: List[List[str]] = []
        queue = sorted([n for n, d in in_degree.items() if d == 0])
        processed = 0

        while queue:
            layers.append(queue)
            next_q: List[str] = []
            for name in queue:
                processed += 1
                for dep in dependents[name]:
                    in_degree[dep] -= 1
                    if in_degree[dep] == 0:
                        next_q.append(dep)
            queue = sorted(next_q)

        if processed != len(self._tasks):
            remaining = [n for n in self._tasks if in_degree[n] > 0]
            raise DependencyCycleError(
                f"Dependency cycle involving: {', '.join(remaining)}"
            )
        return layers

    async def _run_single(self, meta: TaskMeta) -> TaskResult:
        """Run a single task with retries, timeout, and plugin hooks."""
        last_error = ""
        total_start = time.perf_counter()

        for attempt in range(1, meta.retries + 1):
            # Plugin: before_task
            for plugin in self._plugins:
                await plugin.before_task(meta.name)

            await self._bus.emit(TaskEvent(
                timestamp=datetime.now(timezone.utc).isoformat(),
                event_type="task_started",
                task_name=meta.name,
                attempt=attempt,
                details={"max_attempts": meta.retries},
            ))

            start = time.perf_counter()
            try:
                # Build kwargs from dependency results
                kwargs: Dict[str, Any] = {}
                for dep_name in meta.depends_on:
                    dep_result = self._results.get(dep_name)
                    if dep_result and dep_result.status == TaskStatus.SUCCESS:
                        kwargs[dep_name] = dep_result.result

                result = await asyncio.wait_for(
                    meta.fn(**kwargs) if kwargs else meta.fn(),
                    timeout=meta.timeout,
                )
                duration = time.perf_counter() - start

                # Plugin: after_task
                for plugin in self._plugins:
                    await plugin.after_task(meta.name, result)

                await self._bus.emit(TaskEvent(
                    timestamp=datetime.now(timezone.utc).isoformat(),
                    event_type="task_completed",
                    task_name=meta.name,
                    attempt=attempt,
                    duration=duration,
                ))

                return TaskResult(
                    name=meta.name, status=TaskStatus.SUCCESS,
                    result=result, attempts=attempt,
                    duration=round(duration, 3),
                )

            except asyncio.TimeoutError:
                duration = time.perf_counter() - start
                last_error = f"Timed out after {meta.timeout}s"

                for plugin in self._plugins:
                    await plugin.on_error(meta.name, TaskTimeoutError(meta.name, meta.timeout))

                await self._bus.emit(TaskEvent(
                    timestamp=datetime.now(timezone.utc).isoformat(),
                    event_type="task_timeout",
                    task_name=meta.name,
                    attempt=attempt,
                    duration=duration,
                ))

            except Exception as e:
                duration = time.perf_counter() - start
                last_error = f"{type(e).__name__}: {e}"

                for plugin in self._plugins:
                    await plugin.on_error(meta.name, e)

                await self._bus.emit(TaskEvent(
                    timestamp=datetime.now(timezone.utc).isoformat(),
                    event_type="task_failed",
                    task_name=meta.name,
                    attempt=attempt,
                    error=last_error,
                    duration=duration,
                ))

            # Retry backoff
            if attempt < meta.retries:
                delay = min(
                    self._config.retry_delay_base * (2 ** (attempt - 1)),
                    self._config.retry_delay_max,
                )
                await self._bus.emit(TaskEvent(
                    timestamp=datetime.now(timezone.utc).isoformat(),
                    event_type="task_retry",
                    task_name=meta.name,
                    attempt=attempt + 1,
                    details={"delay": delay},
                ))
                await asyncio.sleep(delay)

        total_duration = time.perf_counter() - total_start
        status = TaskStatus.TIMEOUT if "Timed out" in last_error else TaskStatus.FAILED
        return TaskResult(
            name=meta.name, status=status, error=last_error,
            attempts=meta.retries, duration=round(total_duration, 3),
        )

    async def run(self) -> Dict[str, TaskResult]:
        """Execute all tasks respecting dependencies and concurrency."""
        if not self._tasks:
            return {}

        layers = self.get_execution_order()
        semaphore = asyncio.Semaphore(self._config.max_workers)

        await self._bus.emit(TaskEvent(
            timestamp=datetime.now(timezone.utc).isoformat(),
            event_type="scheduler_started",
            task_name="*",
            details={
                "total_tasks": len(self._tasks),
                "max_workers": self._config.max_workers,
                "layers": layers,
            },
        ))

        total_start = time.perf_counter()

        for layer in layers:
            async def _run_in_layer(name: str) -> None:
                meta = self._tasks[name]

                # Check dependencies
                for dep in meta.depends_on:
                    dep_result = self._results.get(dep)
                    if dep_result is None or dep_result.status != TaskStatus.SUCCESS:
                        self._results[name] = TaskResult(
                            name=name, status=TaskStatus.SKIPPED,
                            error=f"Dependency '{dep}' did not succeed",
                        )
                        await self._bus.emit(TaskEvent(
                            timestamp=datetime.now(timezone.utc).isoformat(),
                            event_type="task_skipped",
                            task_name=name,
                            error=f"dependency '{dep}' failed",
                        ))
                        return

                async with semaphore:
                    self._results[name] = await self._run_single(meta)

            await asyncio.gather(*[_run_in_layer(name) for name in layer])

        total_duration = time.perf_counter() - total_start

        # Summary event
        counts = defaultdict(int)
        for r in self._results.values():
            counts[r.status.value] += 1

        await self._bus.emit(TaskEvent(
            timestamp=datetime.now(timezone.utc).isoformat(),
            event_type="scheduler_complete",
            task_name="*",
            duration=total_duration,
            details={
                "total": len(self._results),
                "succeeded": counts.get("success", 0),
                "failed": counts.get("failed", 0),
                "timed_out": counts.get("timeout", 0),
                "skipped": counts.get("skipped", 0),
            },
        ))

        return dict(self._results)

    def print_summary(self, results: Dict[str, TaskResult]) -> None:
        """Print human-readable summary."""
        counts = defaultdict(int)
        for r in results.values():
            counts[r.status.value] += 1
        total_duration = sum(r.duration for r in results.values())

        layers = self.get_execution_order()

        print(f"\n{'='*55}")
        print(f"  Task Automation Framework - Run Summary")
        print(f"{'='*55}")
        print(f"  Config: max_workers={self._config.max_workers}, "
              f"global_timeout={self._config.global_timeout}s")
        print(f"  Total tasks:    {len(results)}")
        print(f"  Succeeded:      {counts.get('success', 0)}")
        print(f"  Failed:         {counts.get('failed', 0)}")
        print(f"  Timed out:      {counts.get('timeout', 0)}")
        print(f"  Skipped:        {counts.get('skipped', 0)}")
        print(f"  Total duration: {total_duration:.1f}s")

        print(f"\n  Execution Order:")
        for i, layer in enumerate(layers):
            mode = "concurrent" if len(layer) > 1 else "sequential"
            dep_note = f", after layer {i-1}" if i > 0 else ""
            print(f"    Layer {i}: {layer}  ({mode}{dep_note})")

        print(f"\n  Task Details:")
        for name, r in sorted(results.items()):
            status = r.status.value.upper()
            retried = f"  (retried {r.attempts - 1}x)" if r.attempts > 1 else ""
            error = f"  Error: {r.error}" if r.error else ""
            print(f"    {name:20s} {status:8s} {r.duration:6.1f}s  "
                  f"{r.attempts}/{self._tasks[name].retries} attempts{retried}{error}")

        if self._plugins:
            print(f"\n  Plugins:")
            for plugin in self._plugins:
                if hasattr(plugin, "summary"):
                    print(f"    {plugin.name}: {plugin.summary()}")

        print(f"{'='*55}")


# ============================================================================
# Example Tasks
# ============================================================================

@task(name="fetch_users", timeout=10.0, retries=3)
async def fetch_users() -> dict:
    """Fetch user data from simulated API."""
    await asyncio.sleep(1.0)
    return {"users": ["Alice", "Bob", "Charlie"], "count": 3}


@task(name="fetch_config", timeout=5.0, retries=1)
async def fetch_config() -> dict:
    """Fetch application config."""
    await asyncio.sleep(0.5)
    return {"theme": "dark", "language": "en"}


@task(name="validate", timeout=5.0, retries=1, depends_on=["fetch_users", "fetch_config"])
async def validate_data(fetch_users: dict = None, fetch_config: dict = None) -> dict:
    """Validate fetched data."""
    await asyncio.sleep(0.3)
    return {"valid": True, "user_count": fetch_users.get("count", 0) if fetch_users else 0}


@task(name="process_users", timeout=15.0, retries=2, depends_on=["validate"])
async def process_users(validate: dict = None) -> dict:
    """Process validated user data."""
    await asyncio.sleep(2.0)
    return {"processed": validate.get("user_count", 0) if validate else 0}


@task(name="generate_report", timeout=10.0, retries=1, depends_on=["process_users"])
async def generate_report(process_users: dict = None) -> str:
    """Generate a summary report."""
    await asyncio.sleep(1.0)
    count = process_users.get("processed", 0) if process_users else 0
    return f"Report: processed {count} users"


@task(name="send_report", timeout=5.0, retries=3, depends_on=["generate_report"])
async def send_report(generate_report: str = None) -> str:
    """Send the report via notification."""
    await asyncio.sleep(0.5)
    return f"Sent: {generate_report}"


@task(name="archive", timeout=5.0, retries=1, depends_on=["generate_report"])
async def archive(generate_report: str = None) -> str:
    """Archive the report."""
    await asyncio.sleep(0.8)
    return f"Archived: {generate_report}"


# ============================================================================
# Main
# ============================================================================

async def main() -> None:
    config = RunnerConfig.from_env()
    runner = TaskRunner(config)
    runner.register_all()
    runner.add_all_plugins()

    results = await runner.run()
    runner.print_summary(results)


if __name__ == "__main__":
    asyncio.run(main())
