## Exercise 1 Solution: Basic Class, BankAccount

```python
from typing import List, Tuple
from datetime import datetime


class InsufficientFundsError(Exception):
    """Raised when a withdrawal exceeds available balance."""

    def __init__(self, amount: float, balance: float):
        self.amount = amount
        self.balance = balance
        super().__init__(
            f"Cannot withdraw ${amount:.2f}: only ${balance:.2f} available"
        )


class BankAccount:
    """A bank account with transaction history."""

    def __init__(self, owner: str, balance: float = 0.0):
        if balance < 0:
            raise ValueError("Initial balance cannot be negative")
        self._owner = owner
        self._balance = balance
        self._transactions: List[Tuple[str, float, float, str]] = []

        if balance > 0:
            self._transactions.append(
                ("initial_deposit", balance, balance, datetime.now().isoformat())
            )

    @property
    def owner(self) -> str:
        return self._owner

    def get_balance(self) -> float:
        """Return the current balance."""
        return self._balance

    def deposit(self, amount: float) -> float:
        """Deposit money. Returns new balance."""
        if amount <= 0:
            raise ValueError(f"Deposit amount must be positive, got {amount}")
        self._balance += amount
        self._transactions.append(
            ("deposit", amount, self._balance, datetime.now().isoformat())
        )
        return self._balance

    def withdraw(self, amount: float) -> float:
        """Withdraw money. Returns new balance."""
        if amount <= 0:
            raise ValueError(f"Withdrawal amount must be positive, got {amount}")
        if amount > self._balance:
            raise InsufficientFundsError(amount, self._balance)
        self._balance -= amount
        self._transactions.append(
            ("withdrawal", amount, self._balance, datetime.now().isoformat())
        )
        return self._balance

    def get_transactions(self) -> List[Tuple[str, float, float, str]]:
        """Return list of (type, amount, balance_after, timestamp) tuples."""
        return list(self._transactions)

    def __repr__(self) -> str:
        return f"BankAccount(owner={self._owner!r}, balance={self._balance:.2f})"

    def __str__(self) -> str:
        return f"BankAccount(owner='{self._owner}', balance=${self._balance:,.2f})"


# Usage example
if __name__ == "__main__":
    acct = BankAccount("Alice", 100.0)
    print(acct)  # BankAccount(owner='Alice', balance=$100.00)

    acct.deposit(50.0)
    print(f"After deposit: {acct.get_balance()}")  # 150.0

    acct.withdraw(30.0)
    print(f"After withdrawal: {acct.get_balance()}")  # 120.0

    print(f"\nTransaction history:")
    for txn_type, amount, balance, ts in acct.get_transactions():
        print(f"  {txn_type}: ${amount:.2f} -> balance: ${balance:.2f}")

    # Test error handling
    try:
        acct.withdraw(500.0)
    except InsufficientFundsError as e:
        print(f"\nError: {e}")

    try:
        acct.deposit(-10)
    except ValueError as e:
        print(f"Error: {e}")

    print(f"\nrepr: {repr(acct)}")
```

## Exercise 2 Solution: Inheritance, Animal Hierarchy

```python
from abc import ABC, abstractmethod
from typing import List


class Animal(ABC):
    """Abstract base class for all animals."""

    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

    @abstractmethod
    def speak(self) -> str:
        """Return the sound this animal makes."""
        pass

    def describe(self) -> str:
        """Describe this animal (uses speak())."""
        return f"{self.name} is a {self.__class__.__name__}, age {self.age}. Says: {self.speak()}"

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(name={self.name!r}, age={self.age})"


class Dog(Animal):
    """A dog that can learn tricks."""

    def __init__(self, name: str, age: int):
        super().__init__(name, age)
        self._tricks: List[str] = []

    def speak(self) -> str:
        return "Woof!"

    def learn_trick(self, trick: str) -> None:
        """Teach this dog a new trick."""
        if trick not in self._tricks:
            self._tricks.append(trick)

    def show_tricks(self) -> List[str]:
        """Return list of known tricks."""
        return list(self._tricks)

    def __repr__(self) -> str:
        return f"Dog(name={self.name!r}, age={self.age}, tricks={self._tricks})"


class Cat(Animal):
    """A cat."""

    def speak(self) -> str:
        return "Meow!"


class Duck(Animal):
    """A duck."""

    def speak(self) -> str:
        return "Quack!"


class Puppy(Dog):
    """A young dog that speaks more quietly."""

    def __init__(self, name: str, age: int):
        super().__init__(name, age)

    def speak(self) -> str:
        parent_sound = super().speak()
        return f"{parent_sound} ...but quieter"

    def __repr__(self) -> str:
        return f"Puppy(name={self.name!r}, age={self.age})"


# Usage example
if __name__ == "__main__":
    # Cannot instantiate abstract class
    try:
        a = Animal("test", 1)
    except TypeError as e:
        print(f"Cannot instantiate Animal: {e}")

    # Create animals
    animals = [
        Dog("Rex", 5),
        Cat("Whiskers", 3),
        Duck("Donald", 2),
        Puppy("Spot", 1),
    ]

    print("\n=== All Animals ===")
    for a in animals:
        print(f"  {a.describe()}")

    # Dog tricks
    print("\n=== Dog Tricks ===")
    rex = animals[0]
    rex.learn_trick("sit")
    rex.learn_trick("shake")
    rex.learn_trick("roll over")
    print(f"  {rex.name} knows: {rex.show_tricks()}")

    # Repr
    print("\n=== Repr ===")
    for a in animals:
        print(f"  {repr(a)}")

    # MRO for Puppy
    print(f"\n=== Puppy MRO ===")
    for cls in Puppy.__mro__:
        print(f"  {cls.__name__}")
