## Exercise 3 Solution: Dunder Methods, Vector Class

```python
import math
from typing import Union, Iterator


class Vector:
    """An n-dimensional vector supporting arithmetic and comparison."""

    def __init__(self, *components: float):
        if not components:
            raise ValueError("Vector must have at least one component")
        self._components = tuple(float(c) for c in components)

    @property
    def components(self) -> tuple:
        return self._components

    def __repr__(self) -> str:
        args = ", ".join(repr(c) for c in self._components)
        return f"Vector({args})"

    def __str__(self) -> str:
        return f"({', '.join(str(c) for c in self._components)})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector):
            return NotImplemented
        return self._components == other._components

    def __hash__(self) -> int:
        return hash(self._components)

    def _check_dimensions(self, other: "Vector", op: str) -> None:
        if len(self) != len(other):
            raise ValueError(
                f"Cannot {op} vectors of dimension {len(self)} and {len(other)}"
            )

    def __add__(self, other: "Vector") -> "Vector":
        if not isinstance(other, Vector):
            return NotImplemented
        self._check_dimensions(other, "add")
        return Vector(*(a + b for a, b in zip(self._components, other._components)))

    def __sub__(self, other: "Vector") -> "Vector":
        if not isinstance(other, Vector):
            return NotImplemented
        self._check_dimensions(other, "subtract")
        return Vector(*(a - b for a, b in zip(self._components, other._components)))

    def __mul__(self, scalar: Union[int, float]) -> "Vector":
        if not isinstance(scalar, (int, float)):
            return NotImplemented
        return Vector(*(c * scalar for c in self._components))

    def __rmul__(self, scalar: Union[int, float]) -> "Vector":
        return self.__mul__(scalar)

    def __neg__(self) -> "Vector":
        return Vector(*(-c for c in self._components))

    def __abs__(self) -> float:
        return math.sqrt(sum(c ** 2 for c in self._components))

    def __len__(self) -> int:
        return len(self._components)

    def __getitem__(self, index: int) -> float:
        return self._components[index]

    def __iter__(self) -> Iterator[float]:
        return iter(self._components)

    def __bool__(self) -> bool:
        return any(c != 0 for c in self._components)

    def __lt__(self, other: "Vector") -> bool:
        if not isinstance(other, Vector):
            return NotImplemented
        return abs(self) < abs(other)

    def dot(self, other: "Vector") -> float:
        """Compute the dot product with another vector."""
        if not isinstance(other, Vector):
            raise TypeError(f"Expected Vector, got {type(other).__name__}")
        self._check_dimensions(other, "dot product")
        return sum(a * b for a, b in zip(self._components, other._components))

    def normalized(self) -> "Vector":
        """Return a unit vector (magnitude 1.0) in the same direction."""
        magnitude = abs(self)
        if magnitude == 0:
            raise ValueError("Cannot normalize a zero vector")
        return Vector(*(c / magnitude for c in self._components))


# Usage example
if __name__ == "__main__":
    v1 = Vector(1, 2, 3)
    v2 = Vector(4, 5, 6)

    print("=== Basic Operations ===")
    print(f"  v1 = {v1}")
    print(f"  v2 = {v2}")
    print(f"  v1 + v2 = {v1 + v2}")
    print(f"  v1 - v2 = {v1 - v2}")
    print(f"  v1 * 3 = {v1 * 3}")
    print(f"  3 * v1 = {3 * v1}")
    print(f"  -v1 = {-v1}")

    print("\n=== Properties ===")
    print(f"  |v1| = {abs(v1):.4f}")
    print(f"  |Vector(3,4)| = {abs(Vector(3, 4))}")  # 5.0
    print(f"  len(v1) = {len(v1)}")
    print(f"  v1[0] = {v1[0]}")
    print(f"  v1.dot(v2) = {v1.dot(v2)}")  # 32

    print("\n=== Comparison ===")
    print(f"  v1 == Vector(1,2,3): {v1 == Vector(1, 2, 3)}")
    print(f"  v1 == v2: {v1 == v2}")
    print(f"  v1 < v2: {v1 < v2}")  # by magnitude

    print("\n=== Hash (sets/dicts) ===")
    v_set = {v1, v2, Vector(1, 2, 3)}  # duplicate removed
    print(f"  Set of vectors: {v_set} (size: {len(v_set)})")

    print("\n=== Iteration ===")
    print(f"  Components: {[c for c in v1]}")

    print("\n=== Normalization ===")
    n = v1.normalized()
    print(f"  v1.normalized() = {n}")
    print(f"  |v1.normalized()| = {abs(n):.10f}")  # ~1.0

    print("\n=== Bool ===")
    print(f"  bool(v1) = {bool(v1)}")
    print(f"  bool(Vector(0,0,0)) = {bool(Vector(0, 0, 0))}")

    print("\n=== Error Handling ===")
    try:
        v1 + Vector(1, 2)
