from functools import total_ordering


ABSOLUTE_ZERO_C = -273.15


@total_ordering
class Temperature:
    """Temperature with automatic conversion between C, F, and K."""

    def __init__(self, celsius: float = 0.0):
        self.celsius = celsius  # Uses the property setter for validation

    @property
    def celsius(self) -> float:
        return self._celsius

    @celsius.setter
    def celsius(self, value: float) -> None:
        if value < ABSOLUTE_ZERO_C:
            raise ValueError(
                f"Temperature {value}C is below absolute zero ({ABSOLUTE_ZERO_C}C)"
            )
        self._celsius = value

    @property
    def fahrenheit(self) -> float:
        return self._celsius * 9 / 5 + 32

    @fahrenheit.setter
    def fahrenheit(self, value: float) -> None:
        self.celsius = (value - 32) * 5 / 9

    @property
    def kelvin(self) -> float:
        return self._celsius - ABSOLUTE_ZERO_C

    @kelvin.setter
    def kelvin(self, value: float) -> None:
        self.celsius = value + ABSOLUTE_ZERO_C

    @classmethod
    def from_fahrenheit(cls, f: float) -> "Temperature":
        """Create Temperature from Fahrenheit value."""
        return cls((f - 32) * 5 / 9)

    @classmethod
    def from_kelvin(cls, k: float) -> "Temperature":
        """Create Temperature from Kelvin value."""
        return cls(k + ABSOLUTE_ZERO_C)

    def __repr__(self) -> str:
        return f"Temperature(celsius={self._celsius:.2f})"

    def __str__(self) -> str:
        return f"{self._celsius:.1f}C / {self.fahrenheit:.1f}F / {self.kelvin:.2f}K"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Temperature):
            return NotImplemented
        return abs(self._celsius - other._celsius) < 0.01

    def __lt__(self, other: "Temperature") -> bool:
        if not isinstance(other, Temperature):
            return NotImplemented
        return self._celsius < other._celsius


# Usage example
if __name__ == "__main__":
    print("=== Basic Conversions ===")
    t = Temperature(100)
    print(f"  100C = {t}")
    print(f"  Fahrenheit: {t.fahrenheit}")  # 212.0
    print(f"  Kelvin: {t.kelvin}")          # 373.15

    print("\n=== Setting via Properties ===")
    t.fahrenheit = 32
    print(f"  Set F=32: {t}")  # 0.0C
    t.kelvin = 0
    print(f"  Set K=0: {t}")   # -273.15C

    print("\n=== Class Methods ===")
    t2 = Temperature.from_fahrenheit(212)
    print(f"  from_fahrenheit(212): {t2}")  # 100.0C
    t3 = Temperature.from_kelvin(0)
    print(f"  from_kelvin(0): {t3}")        # -273.15C

    print("\n=== Comparison ===")
    boiling = Temperature(100)
    also_boiling = Temperature.from_fahrenheit(212)
    freezing = Temperature(0)
    print(f"  100C == from_F(212): {boiling == also_boiling}")  # True
    print(f"  0C < 100C: {freezing < boiling}")                 # True
    print(f"  Sorted: {sorted([boiling, freezing, Temperature(50)])}")

    print("\n=== Validation ===")
    try:
        Temperature(-300)  # Below absolute zero
    except ValueError as e:
        print(f"  Error: {e}")

    try:
        t = Temperature(0)
        t.kelvin = -10  # Below absolute zero
    except ValueError as e:
        print(f"  Error: {e}")
