from dataclasses import dataclass, field
from typing import List, Optional, Dict
from datetime import date, timedelta


@dataclass
class Author:
    """Represents a book author."""
    name: str
    birth_year: int
    nationality: str

    def __str__(self) -> str:
        return f"{self.name} ({self.nationality}, b. {self.birth_year})"


@dataclass(order=True)
class Book:
    """Represents a book in the library."""
    sort_index: str = field(init=False, repr=False)
    title: str
    author: Author
    isbn: str
    published_date: date
    genres: List[str] = field(default_factory=list)
    checked_out: bool = field(default=False, init=False)
    due_date: Optional[date] = field(default=None, init=False)

    def __post_init__(self):
        # Set sort index to title for ordering
        self.sort_index = self.title.lower()

        # Validate ISBN: must be 10 or 13 digits
        digits = self.isbn.replace("-", "")
        if not digits.isdigit() or len(digits) not in (10, 13):
            raise ValueError(
                f"ISBN must be 10 or 13 digits, got '{self.isbn}' ({len(digits)} digits)"
            )

    def __str__(self) -> str:
        status = "CHECKED OUT" if self.checked_out else "Available"
        return f"'{self.title}' by {self.author.name} [{status}]"


@dataclass
class Library:
    """Manages a collection of books."""
    name: str
    books: List[Book] = field(default_factory=list)

    def add_book(self, book: Book) -> None:
        """Add a book to the library."""
        # Check for duplicate ISBN
        for existing in self.books:
            if existing.isbn == book.isbn:
                raise ValueError(f"Book with ISBN {book.isbn} already exists")
        self.books.append(book)

    def remove_book(self, isbn: str) -> Book:
        """Remove and return a book by ISBN."""
        for i, book in enumerate(self.books):
            if book.isbn == isbn:
                return self.books.pop(i)
        raise KeyError(f"No book found with ISBN {isbn}")

    def find_by_author(self, author_name: str) -> List[Book]:
        """Find all books by an author name (case-insensitive partial match)."""
        return [
            b for b in self.books
            if author_name.lower() in b.author.name.lower()
        ]

    def find_by_genre(self, genre: str) -> List[Book]:
        """Find all books in a genre (case-insensitive)."""
        return [
            b for b in self.books
            if genre.lower() in [g.lower() for g in b.genres]
        ]

    def checkout(self, isbn: str, days: int = 14) -> Book:
        """Check out a book by ISBN. Sets due date to today + days."""
        for book in self.books:
            if book.isbn == isbn:
                if book.checked_out:
                    raise ValueError(f"'{book.title}' is already checked out")
                book.checked_out = True
                book.due_date = date.today() + timedelta(days=days)
                return book
        raise KeyError(f"No book found with ISBN {isbn}")

    def return_book(self, isbn: str) -> Book:
        """Return a checked-out book."""
        for book in self.books:
            if book.isbn == isbn:
                if not book.checked_out:
                    raise ValueError(f"'{book.title}' is not checked out")
                book.checked_out = False
                book.due_date = None
                return book
        raise KeyError(f"No book found with ISBN {isbn}")

    def overdue_books(self) -> List[Book]:
        """Return all books that are overdue (checked out and past due date)."""
        today = date.today()
        return [
            b for b in self.books
            if b.checked_out and b.due_date is not None and b.due_date < today
        ]

    def available_books(self) -> List[Book]:
        """Return all books that are available for checkout."""
        return [b for b in self.books if not b.checked_out]

    def __len__(self) -> int:
        return len(self.books)

    def __contains__(self, isbn: str) -> bool:
        return any(b.isbn == isbn for b in self.books)


# Usage example
if __name__ == "__main__":
    # Create authors
