from abc import ABC, abstractmethod
from typing import List, Optional


# ============================================================================
# Component: Engine
# ============================================================================

class Engine(ABC):
    """Abstract engine component."""

    def __init__(self):
        self._running = False

    @property
    @abstractmethod
    def fuel_type(self) -> str:
        pass

    def start(self) -> str:
        if self._running:
            return f"{self.fuel_type} engine already running"
        self._running = True
        return f"{self.fuel_type} engine started"

    def stop(self) -> str:
        if not self._running:
            return f"{self.fuel_type} engine already stopped"
        self._running = False
        return f"{self.fuel_type} engine stopped"

    @property
    def is_running(self) -> bool:
        return self._running

    def __repr__(self) -> str:
        state = "ON" if self._running else "OFF"
        return f"{self.__class__.__name__}({state})"


class GasEngine(Engine):
    @property
    def fuel_type(self) -> str:
        return "Gasoline"


class ElectricMotor(Engine):
    @property
    def fuel_type(self) -> str:
        return "Electric"


class DieselEngine(Engine):
    @property
    def fuel_type(self) -> str:
        return "Diesel"


# ============================================================================
# Component: Cargo
# ============================================================================

class Cargo(ABC):
    """Abstract cargo component."""

    def __init__(self, capacity: int):
        self._items: List[str] = []
        self._capacity = capacity

    @property
    @abstractmethod
    def cargo_type(self) -> str:
        pass

    def load(self, item: str) -> str:
        if len(self._items) >= self._capacity:
            return f"{self.cargo_type} is full (capacity: {self._capacity})"
        self._items.append(item)
        return f"Loaded '{item}' into {self.cargo_type}"

    def unload(self, item: str) -> str:
        if item not in self._items:
            return f"'{item}' not found in {self.cargo_type}"
        self._items.remove(item)
        return f"Unloaded '{item}' from {self.cargo_type}"

    @property
    def contents(self) -> List[str]:
        return list(self._items)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({len(self._items)}/{self._capacity})"


class Trunk(Cargo):
    def __init__(self, capacity: int = 5):
        super().__init__(capacity)

    @property
    def cargo_type(self) -> str:
        return "Trunk"


class FlatBed(Cargo):
    def __init__(self, capacity: int = 20):
        super().__init__(capacity)

    @property
    def cargo_type(self) -> str:
        return "Flat Bed"


# ============================================================================
# Component: Battery
# ============================================================================

class Battery:
    """Battery component for electric/hybrid vehicles."""

    def __init__(self, capacity_kwh: float = 75.0):
        self._capacity = capacity_kwh
        self._level = capacity_kwh  # Start fully charged

    def charge(self, amount: float = None) -> str:
        if amount is None:
            amount = self._capacity - self._level
        self._level = min(self._capacity, self._level + amount)
        return f"Charged to {self._level:.1f}/{self._capacity:.1f} kWh"

    def discharge(self, amount: float) -> str:
        if amount > self._level:
            return f"Insufficient charge: {self._level:.1f} kWh available"
        self._level -= amount
        return f"Discharged {amount:.1f} kWh, remaining: {self._level:.1f} kWh"

    @property
    def level(self) -> float:
        return self._level

    @property
    def percentage(self) -> float:
        return (self._level / self._capacity) * 100

    def __repr__(self) -> str:
        return f"Battery({self._level:.1f}/{self._capacity:.1f} kWh)"


# ============================================================================
# Vehicle: Composed from components
# ============================================================================

class Vehicle:
    """A vehicle composed of engine, cargo, and optional battery components."""

    def __init__(
        self,
        name: str,
        engine: Engine,
        cargo: Optional[Cargo] = None,
        battery: Optional[Battery] = None,
    ):
        self.name = name
        self.engine = engine
        self.cargo = cargo
        self.battery = battery

    def start(self) -> str:
        """Start the vehicle's engine."""
        return self.engine.start()

    def stop(self) -> str:
        """Stop the vehicle's engine."""
        return self.engine.stop()

    def load(self, item: str) -> str:
        """Load an item into cargo."""
        if self.cargo is None:
            return f"{self.name} has no cargo area"
        return self.cargo.load(item)

    def unload(self, item: str) -> str:
        """Unload an item from cargo."""
        if self.cargo is None:
            return f"{self.name} has no cargo area"
        return self.cargo.unload(item)

    def charge(self, amount: float = None) -> str:
        """Charge the battery."""
        if self.battery is None:
            return f"{self.name} has no battery"
        return self.battery.charge(amount)

    @property
    def status(self) -> str:
        parts = [f"{self.name}:"]
        parts.append(f"  Engine: {self.engine}")
        if self.cargo:
            parts.append(f"  Cargo: {self.cargo}")
        if self.battery:
            parts.append(f"  Battery: {self.battery} ({self.battery.percentage:.0f}%)")
        return "\n".join(parts)

    def __repr__(self) -> str:
        components = [f"engine={self.engine!r}"]
        if self.cargo:
            components.append(f"cargo={self.cargo!r}")
        if self.battery:
            components.append(f"battery={self.battery!r}")
        return f"Vehicle(name={self.name!r}, {', '.join(components)})"


# Usage example
if __name__ == "__main__":
    # Create different vehicle configurations using composition
    gas_car = Vehicle("Sedan", GasEngine(), Trunk())
    electric_car = Vehicle("Tesla Model 3", ElectricMotor(), Trunk(), Battery(82.0))
    pickup = Vehicle("F-150", GasEngine(), FlatBed())
    hybrid = Vehicle("Prius", GasEngine(), Trunk(capacity=4), Battery(8.8))
    motorcycle = Vehicle("Harley", GasEngine())  # No cargo, no battery
    delivery_van = Vehicle("Sprinter", DieselEngine(), FlatBed(capacity=50))

    vehicles = [gas_car, electric_car, pickup, hybrid, motorcycle, delivery_van]

    print("=== Vehicle Configurations ===")
    for v in vehicles:
        print(f"  {repr(v)}")

    print("\n=== Gas Car ===")
    print(f"  {gas_car.start()}")
    print(f"  {gas_car.load('suitcase')}")
    print(f"  {gas_car.load('groceries')}")
    print(f"  {gas_car.charge()}")  # No battery
    print(f"  {gas_car.stop()}")

    print("\n=== Electric Car ===")
    print(f"  {electric_car.start()}")
    print(f"  Battery: {electric_car.battery.percentage:.0f}%")
    electric_car.battery.discharge(20)
    print(f"  After drive: {electric_car.battery.percentage:.0f}%")
    print(f"  {electric_car.charge()}")
    print(f"  After charge: {electric_car.battery.percentage:.0f}%")

    print("\n=== Pickup ===")
    print(f"  {pickup.load('lumber')}")
    print(f"  {pickup.load('cement bags')}")
