## Exercise 1 Solution: Basic Decorator, @timer

```python
import time
import functools
from typing import Callable, Any


def timer(func: Callable) -> Callable:
    """Decorator that logs function execution time."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"[TIMER] {func.__name__} took {elapsed:.4f}s")
        return result

    return wrapper


# Usage example
@timer
def slow_function(n: float) -> str:
    """Simulate a slow function."""
    time.sleep(n)
    return f"Slept for {n}s"


@timer
def fast_add(a: int, b: int) -> int:
    """Add two numbers."""
    return a + b


@timer
def fibonacci(n: int) -> int:
    """Compute Fibonacci number recursively (slow for large n)."""
    if n <= 1:
        return n
    return fibonacci.__wrapped__(n - 1) + fibonacci.__wrapped__(n - 2)


if __name__ == "__main__":
    result = slow_function(0.5)
    print(f"Result: {result}")

    result = fast_add(3, 7)
    print(f"Result: {result}")

    # Verify metadata is preserved
    print(f"\nName preserved: {slow_function.__name__}")  # "slow_function"
    print(f"Doc preserved: {slow_function.__doc__}")       # "Simulate a slow function."
    print(f"Has __wrapped__: {hasattr(slow_function, '__wrapped__')}")

    # Works with keyword arguments
    result = fast_add(a=10, b=20)
    print(f"Kwargs result: {result}")
```

## Exercise 2 Solution: @functools.wraps, Fix a Broken Decorator

```python
import functools
from typing import Callable, Any, Optional


# BROKEN version (loses metadata)
def broken_logger(func: Callable) -> Callable:
    def wrapper(*args, **kwargs):
        print(f"Calling function...")
        result = func(*args, **kwargs)
        print(f"Function returned: {result}")
        return result
    return wrapper


# FIXED version (preserves metadata)
def working_logger(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        print(f"Calling {func.__name__}...")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned: {result}")
        return result
    return wrapper


# FLEXIBLE decorator: works with or without arguments
def flexible(func: Optional[Callable] = None, *, prefix: str = "INFO") -> Callable:
    """A decorator that works both with and without arguments.

    Usage:
        @flexible          # No arguments
        @flexible()        # No arguments (explicit)
        @flexible(prefix="DEBUG")  # With arguments
    """
    def decorator(fn: Callable) -> Callable:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs) -> Any:
            print(f"[{prefix}] Calling {fn.__name__}")
            result = fn(*args, **kwargs)
            print(f"[{prefix}] {fn.__name__} returned: {result}")
            return result
        return wrapper

    if func is not None:
        # Called without arguments: @flexible
        return decorator(func)
    else:
        # Called with arguments: @flexible(prefix="DEBUG")
        return decorator


# Usage example
if __name__ == "__main__":
    # Demonstrate the difference
    @broken_logger
    def greet_broken(name: str) -> str:
        """Greet someone by name."""
        return f"Hello, {name}!"

    @working_logger
    def greet_fixed(name: str) -> str:
        """Greet someone by name."""
        return f"Hello, {name}!"

    print("=== Broken Decorator ===")
    print(f"  __name__: {greet_broken.__name__}")    # "wrapper"
    print(f"  __doc__:  {greet_broken.__doc__}")      # None
    greet_broken("Alice")

    print("\n=== Fixed Decorator ===")
    print(f"  __name__: {greet_fixed.__name__}")     # "greet_fixed"
    print(f"  __doc__:  {greet_fixed.__doc__}")       # "Greet someone by name."
    greet_fixed("Bob")

    print("\n=== help() comparison ===")
    print("Broken:")
    help(greet_broken)
    print("Fixed:")
    help(greet_fixed)

    # Flexible decorator tests
    print("\n=== Flexible Decorator ===")

    @flexible
    def add(a: int, b: int) -> int:
        """Add two numbers."""
        return a + b

    @flexible(prefix="DEBUG")
    def multiply(a: int, b: int) -> int:
        """Multiply two numbers."""
        return a * b

    @flexible()
    def subtract(a: int, b: int) -> int:
        """Subtract two numbers."""
        return a - b

    add(3, 4)
    multiply(3, 4)
    subtract(10, 3)

    # Metadata preserved
    print(f"\nadd.__name__: {add.__name__}")
    print(f"multiply.__name__: {multiply.__name__}")
    print(f"subtract.__name__: {subtract.__name__}")
```

## Exercise 3 Solution: Decorator with Arguments, @retry

```python
import time
import functools
from typing import Callable, Type, Tuple, Any


def retry(
    max_attempts: int = 3,
    delay: float = 1.0,
    exceptions: Tuple[Type[Exception], ...] = (Exception,),
    backoff: float = 1.0,
) -> Callable:
    """Decorator factory that retries a function on failure.

    Args:
        max_attempts: Maximum number of attempts (including first try).
        delay: Base delay between retries in seconds.
        exceptions: Tuple of exception types to catch.
        backoff: Multiplier for delay on each retry (1.0 = constant, 2.0 = exponential).
    """

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            last_exception = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempt < max_attempts:
                        wait_time = delay * (backoff ** (attempt - 1))
                        print(
                            f"[RETRY] {func.__name__} attempt {attempt}/{max_attempts} "
                            f"failed: {e}. Retrying in {wait_time:.1f}s..."
                        )
                        time.sleep(wait_time)
                    else:
                        print(
                            f"[RETRY] {func.__name__} all {max_attempts} attempts failed"
                        )

            raise last_exception

        return wrapper

    return decorator


# Usage example
if __name__ == "__main__":
    # Test 1: Eventually succeeds
    print("=== Test 1: Succeeds on 3rd attempt ===")
    call_count = 0

    @retry(max_attempts=5, delay=0.1, exceptions=(ConnectionError,))
    def unreliable_api():
        """Simulate unreliable API."""
        global call_count
        call_count += 1
        if call_count < 3:
            raise ConnectionError(f"Connection refused (attempt {call_count})")
        return {"status": "success", "attempt": call_count}

    result = unreliable_api()
    print(f"Result: {result}")

    # Test 2: All attempts fail
    print("\n=== Test 2: All attempts fail ===")

    @retry(max_attempts=3, delay=0.1, exceptions=(ValueError,))
    def always_fails():
        """Always raises ValueError."""
        raise ValueError("Permanent failure")

    try:
        always_fails()
    except ValueError as e:
        print(f"Caught expected error: {e}")

    # Test 3: Exponential backoff
    print("\n=== Test 3: Exponential backoff ===")
    attempt_times = []

    @retry(max_attempts=4, delay=0.1, backoff=2.0, exceptions=(RuntimeError,))
    def backoff_test():
        """Test exponential backoff."""
        attempt_times.append(time.perf_counter())
        raise RuntimeError("Keeps failing")

    try:
        backoff_test()
    except RuntimeError:
        pass

    for i in range(1, len(attempt_times)):
        gap = attempt_times[i] - attempt_times[i - 1]
        print(f"  Gap between attempt {i} and {i + 1}: {gap:.2f}s")

    # Test 4: Wrong exception type (not caught, fails immediately)
    print("\n=== Test 4: Uncaught exception type ===")

    @retry(max_attempts=3, delay=0.1, exceptions=(ConnectionError,))
    def wrong_exception():
        raise TypeError("This is not a ConnectionError")

    try:
        wrong_exception()
    except TypeError as e:
        print(f"Not retried (different exception type): {e}")

    # Metadata preserved
    print(f"\nunreliable_api.__name__: {unreliable_api.__name__}")
    print(f"unreliable_api.__doc__: {unreliable_api.__doc__}")
```

## Exercise 4 Solution: Class Decorator, @singleton

```python
import functools
from typing import Type, Any


def singleton(cls: Type) -> Type:
    """Decorator that ensures only one instance of a class exists."""
    instance = None

    @functools.wraps(cls, updated=[])
    class SingletonWrapper(cls):
        def __new__(wrapper_cls, *args, **kwargs):
            nonlocal instance
            if instance is None:
                instance = super().__new__(wrapper_cls)
            return instance

        @classmethod
        def _reset(wrapper_cls):
            """Reset the singleton (for testing)."""
            nonlocal instance
            instance = None

    # Preserve class metadata
    SingletonWrapper.__name__ = cls.__name__
    SingletonWrapper.__qualname__ = cls.__qualname__
    SingletonWrapper.__doc__ = cls.__doc__

    return SingletonWrapper


class CallCounter:
    """A class-based decorator that tracks function call count."""

    def __init__(self, func: Any):
        functools.update_wrapper(self, func)
        self._func = func
        self._call_count = 0

    def __call__(self, *args, **kwargs) -> Any:
        self._call_count += 1
        return self._func(*args, **kwargs)

    @property
    def call_count(self) -> int:
        return self._call_count

    def reset(self) -> None:
        """Reset the call counter to zero."""
        self._call_count = 0

    def __repr__(self) -> str:
        return f"CallCounter({self.__name__}, calls={self._call_count})"


# Usage example
if __name__ == "__main__":
    # Singleton test
    print("=== Singleton ===")

    @singleton
    class Database:
        """Database connection manager."""

        def __init__(self, url: str = "localhost"):
            self.url = url
            print(f"  Connecting to {url}...")

        def query(self, sql: str) -> str:
            return f"Results from {self.url}: {sql}"

    db1 = Database("prod.db.com")
    db2 = Database("other.db.com")  # Returns same instance, __init__ runs again but object is same
    print(f"  db1 is db2: {db1 is db2}")   # True
    print(f"  db1.url: {db1.url}")
    print(f"  Class name: {Database.__name__}")  # "Database"
    print(f"  Class doc: {Database.__doc__}")     # "Database connection manager."

    # Reset singleton for testing
    Database._reset()
    db3 = Database("new.db.com")
    print(f"  db1 is db3: {db1 is db3}")  # False (after reset)

    # CallCounter test
    print("\n=== CallCounter ===")

    @CallCounter
    def say_hello(name: str) -> str:
        """Say hello to someone."""
        return f"Hello, {name}!"

    print(f"  {say_hello('Alice')}")
    print(f"  {say_hello('Bob')}")
    print(f"  {say_hello('Charlie')}")
    print(f"  Call count: {say_hello.call_count}")  # 3
    print(f"  Name: {say_hello.__name__}")           # "say_hello"
    print(f"  Doc: {say_hello.__doc__}")              # "Say hello to someone."
    print(f"  Repr: {repr(say_hello)}")

    say_hello.reset()
    print(f"  After reset: {say_hello.call_count}")  # 0

    say_hello("Diana")
    print(f"  After one call: {say_hello.call_count}")  # 1

    # Multiple independent counters
    print("\n=== Independent Counters ===")

    @CallCounter
    def func_a():
        return "A"

    @CallCounter
    def func_b():
        return "B"

    func_a()
    func_a()
    func_b()
    print(f"  func_a calls: {func_a.call_count}")  # 2
    print(f"  func_b calls: {func_b.call_count}")  # 1
```

## Exercise 5 Solution: Stacking Decorators, Order Matters

```python
import functools
from typing import Callable, Any


def log_calls(func: Callable) -> Callable:
    """Decorator that logs function calls and returns."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        args_str = ", ".join(
            [repr(a) for a in args] + [f"{k}={v!r}" for k, v in kwargs.items()]
        )
        print(f"  -> Calling {func.__name__}({args_str})")
        result = func(*args, **kwargs)
        print(f"  <- {func.__name__} returned {result!r}")
        return result

    return wrapper


def validate_positive(func: Callable) -> Callable:
    """Decorator that ensures all numeric arguments are positive."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        for i, arg in enumerate(args):
            if isinstance(arg, (int, float)) and arg < 0:
                raise ValueError(
                    f"Argument {i} to {func.__name__} must be positive, got {arg}"
                )
        for key, val in kwargs.items():
            if isinstance(val, (int, float)) and val < 0:
                raise ValueError(
                    f"Argument '{key}' to {func.__name__} must be positive, got {val}"
                )
        return func(*args, **kwargs)

    return wrapper


def uppercase(func: Callable) -> Callable:
    """Decorator that converts string return values to uppercase."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        result = func(*args, **kwargs)
        if isinstance(result, str):
            return result.upper()
        return result

    return wrapper


def exclaim(func: Callable) -> Callable:
    """Decorator that adds '!' to string return values."""

    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        result = func(*args, **kwargs)
        if isinstance(result, str):
            return result + "!"
        return result

    return wrapper


# Usage example
if __name__ == "__main__":
    # =====================================================================
    # Order 1: @log_calls wraps @validate_positive wraps add
    # Execution: log_calls.wrapper -> validate_positive.wrapper -> add
    # =====================================================================
    print("=== Order 1: @log_calls over @validate_positive ===")
    print("(log_calls sees the call FIRST, then validate_positive checks)")

    @log_calls
    @validate_positive
    def add_order1(a: int, b: int) -> int:
        return a + b

    add_order1(3, 4)
    # Output: log shows call, validation passes, function runs

    print("\nWith negative argument:")
    try:
        add_order1(-1, 4)
        # Output: log shows call, THEN validation raises
    except ValueError as e:
        print(f"  Error: {e}")

    # =====================================================================
    # Order 2: @validate_positive wraps @log_calls wraps add
    # Execution: validate_positive.wrapper -> log_calls.wrapper -> add
    # =====================================================================
    print("\n=== Order 2: @validate_positive over @log_calls ===")
    print("(validate_positive checks FIRST, log_calls only fires if valid)")

    @validate_positive
    @log_calls
    def add_order2(a: int, b: int) -> int:
        return a + b

    add_order2(3, 4)

    print("\nWith negative argument:")
    try:
        add_order2(-1, 4)
        # Output: validation raises BEFORE log_calls ever fires
    except ValueError as e:
        print(f"  Error: {e}")

    # =====================================================================
    # KEY DIFFERENCE:
    # Order 1: log_calls fires even when validation fails
    # Order 2: log_calls never fires if validation fails
    # Because @A @B def f means f = A(B(f))
    #   Order 1: f = log_calls(validate_positive(original_f))
    #   Order 2: f = validate_positive(log_calls(original_f))
    # =====================================================================

    # =====================================================================
    # Return value transformation: @uppercase and @exclaim
    # =====================================================================
    print("\n=== @uppercase over @exclaim ===")
    print("exclaim runs first (adds !), then uppercase runs (uppercases all)")

    @uppercase
    @exclaim
    def greet_ue(name: str) -> str:
        return f"hello, {name}"

    # exclaim: "hello, alice" -> "hello, alice!"
    # uppercase: "hello, alice!" -> "HELLO, ALICE!"
    print(f"  Result: {greet_ue('alice')}")  # "HELLO, ALICE!"

    print("\n=== @exclaim over @uppercase ===")
    print("uppercase runs first (uppercases), then exclaim runs (adds !)")

    @exclaim
    @uppercase
    def greet_eu(name: str) -> str:
        return f"hello, {name}"

    # uppercase: "hello, alice" -> "HELLO, ALICE"
    # exclaim: "HELLO, ALICE" -> "HELLO, ALICE!"
    print(f"  Result: {greet_eu('alice')}")  # "HELLO, ALICE!"

    # In this case the results look similar, but consider:
    print("\n=== Different results with exclaim adding '!!!' ===")

    def triple_exclaim(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return result + "!!!" if isinstance(result, str) else result
        return wrapper

    @uppercase
    @triple_exclaim
    def msg1(text):
        return text

    @triple_exclaim
    @uppercase
    def msg2(text):
        return text

    print(f"  @uppercase(@triple_exclaim(f)): {msg1('hello')}")
    # triple_exclaim: "hello" -> "hello!!!"
    # uppercase: "hello!!!" -> "HELLO!!!"
    print(f"  @triple_exclaim(@uppercase(f)): {msg2('hello')}")
    # uppercase: "hello" -> "HELLO"
    # triple_exclaim: "HELLO" -> "HELLO!!!"
    # Same in this case, but the execution path differs
