## Exercise 6 Solution: Registration Pattern, @register

```python
import functools
from typing import Callable, Dict, List, Optional, Any


class Registry:
    """A function registry using decorator-based registration."""

    def __init__(self, name: str = "default"):
        self.name = name
        self._registry: Dict[str, dict] = {}

    def register(
        self,
        func: Optional[Callable] = None,
        *,
        name: Optional[str] = None,
        tags: Optional[List[str]] = None,
    ) -> Callable:
        """Register a function. Works as @registry.register or @registry.register(name=..., tags=...)."""

        def decorator(fn: Callable) -> Callable:
            reg_name = name if name is not None else fn.__name__
            self._registry[reg_name] = {
                "function": fn,
                "name": reg_name,
                "tags": tags or [],
                "doc": fn.__doc__ or "",
            }
            return fn  # Return original function unchanged

        if func is not None:
            # Called as @registry.register (without arguments)
            return decorator(func)
        else:
            # Called as @registry.register(name=..., tags=...)
            return decorator

    def get(self, name: str) -> Callable:
        """Get a registered function by name."""
        if name not in self._registry:
            available = ", ".join(sorted(self._registry.keys()))
            raise KeyError(f"Unknown function: '{name}'. Available: {available}")
        return self._registry[name]["function"]

    def list_all(self) -> List[str]:
        """Return sorted list of all registered names."""
        return sorted(self._registry.keys())

    def find_by_tag(self, tag: str) -> List[Callable]:
        """Return functions with the given tag."""
        return [
            entry["function"]
            for entry in self._registry.values()
            if tag in entry["tags"]
        ]

    def run_all(self, *args, **kwargs) -> Dict[str, Any]:
        """Execute all registered functions with the same arguments."""
        results = {}
        for name in sorted(self._registry.keys()):
            entry = self._registry[name]
            results[name] = entry["function"](*args, **kwargs)
        return results

    def info(self) -> List[dict]:
        """Return metadata for all registered functions."""
        return [
            {"name": e["name"], "tags": e["tags"], "doc": e["doc"]}
            for e in sorted(self._registry.values(), key=lambda e: e["name"])
        ]

    def __len__(self) -> int:
        return len(self._registry)

    def __repr__(self) -> str:
        return f"Registry(name={self.name!r}, entries={len(self._registry)})"


class CLI:
    """A simple command-line dispatcher using decorator registration."""

    def __init__(self, name: str = "app"):
        self.name = name
        self._commands: Dict[str, dict] = {}

    def command(
        self,
        func: Optional[Callable] = None,
        *,
        name: Optional[str] = None,
        help: str = "",
    ) -> Callable:
        """Register a CLI command."""

        def decorator(fn: Callable) -> Callable:
            cmd_name = name if name is not None else fn.__name__
            self._commands[cmd_name] = {
                "function": fn,
                "name": cmd_name,
                "help": help or fn.__doc__ or "No description",
            }
            return fn

        if func is not None:
            return decorator(func)
        return decorator

    def run(self, command_name: str, *args, **kwargs) -> Any:
        """Run a command by name."""
        if command_name not in self._commands:
            available = ", ".join(sorted(self._commands.keys()))
            raise KeyError(
                f"Unknown command: '{command_name}'. "
                f"Available commands: {available}"
            )
        return self._commands[command_name]["function"](*args, **kwargs)

    def help_text(self) -> str:
        """Generate help text for all commands."""
        lines = [f"Usage: {self.name} <command> [args...]", "", "Commands:"]
        for name in sorted(self._commands.keys()):
            cmd = self._commands[name]
            lines.append(f"  {name:20s} {cmd['help']}")
        return "\n".join(lines)

    def __repr__(self) -> str:
        return f"CLI(name={self.name!r}, commands={len(self._commands)})"


# Usage example
if __name__ == "__main__":
    # =========================================
    # Registry
    # =========================================
    print("=== Registry ===")
    registry = Registry("math_ops")

    @registry.register(tags=["math", "basic"])
    def add(a: int, b: int) -> int:
        """Add two numbers."""
        return a + b

    @registry.register(name="multiply", tags=["math", "basic"])
    def mul(a: int, b: int) -> int:
        """Multiply two numbers."""
        return a * b

    @registry.register(tags=["string"])
    def greet(name: str) -> str:
        """Greet someone."""
        return f"Hello, {name}!"

    @registry.register(tags=["math", "advanced"])
    def power(a: int, b: int) -> int:
        """Raise a to the power of b."""
        return a ** b

    print(f"  Registry: {registry}")
    print(f"  All commands: {registry.list_all()}")
    print(f"  Math functions: {[f.__name__ for f in registry.find_by_tag('math')]}")
    print(f"  Basic functions: {[f.__name__ for f in registry.find_by_tag('basic')]}")

    # Get and call
    print(f"\n  add(3, 4) = {registry.get('add')(3, 4)}")
    print(f"  multiply(3, 4) = {registry.get('multiply')(3, 4)}")

    # Run all math ops with same args
    print(f"\n  Run all with (3, 4):")
    results = registry.run_all(3, 4)
    for name, result in results.items():
        print(f"    {name}: {result}")

    # Info
    print(f"\n  Plugin info:")
    for info in registry.info():
        print(f"    {info['name']}: {info['doc']} (tags: {info['tags']})")

    # Error handling
    try:
        registry.get("unknown")
    except KeyError as e:
        print(f"\n  Error: {e}")

    # =========================================
    # CLI
    # =========================================
    print("\n=== CLI ===")
    cli = CLI("myapp")

    @cli.command(help="Greet a user by name")
    def hello(name: str) -> None:
        print(f"Hello, {name}!")

    @cli.command(help="Show the current version")
    def version() -> None:
        print("myapp v1.0.0")

    @cli.command(name="add-numbers", help="Add two numbers")
    def add_nums(a: str, b: str) -> None:
