## Mini-Project Solution: Plugin System

```python
import functools
from typing import (
    Any, Callable, Dict, List, Optional, Set, Tuple
)
from collections import defaultdict


# ============================================================================
# Exceptions
# ============================================================================

class PluginError(Exception):
    """Base exception for plugin system errors."""
    pass


class PluginNotFoundError(PluginError):
    """Raised when a plugin is not found in the registry."""
    pass


class MissingDependencyError(PluginError):
    """Raised when a plugin's dependency is not registered."""
    pass


class CircularDependencyError(PluginError):
    """Raised when circular dependencies are detected."""
    pass


class HookError(PluginError):
    """Raised when a hook fails."""
    pass


# ============================================================================
# Global Registries (module-level, populated by decorators)
# ============================================================================

_plugin_registry: Dict[str, dict] = {}
_before_hooks: Dict[str, List[Callable]] = defaultdict(list)
_after_hooks: Dict[str, List[Callable]] = defaultdict(list)


# ============================================================================
# Decorators
# ============================================================================

def plugin(
    name: str,
    version: str,
    depends_on: Optional[List[str]] = None,
) -> Callable:
    """Decorator factory that registers a function as a plugin.

    Args:
        name: Unique plugin identifier.
        version: Semantic version string.
        depends_on: List of plugin names this plugin requires.
    """
    deps = depends_on or []

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            return func(*args, **kwargs)

        _plugin_registry[name] = {
            "name": name,
            "version": version,
            "depends_on": list(deps),
            "function": wrapper,
            "doc": func.__doc__ or "",
            "before_hooks": [],
            "after_hooks": [],
            "loaded": False,
        }

        return wrapper

    return decorator


def before_hook(plugin_name: str) -> Callable:
    """Decorator factory that registers a before-hook for a plugin.

    The hook function receives (context) and can modify it or raise to abort.
    """

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            return func(*args, **kwargs)

        _before_hooks[plugin_name].append(wrapper)
        return wrapper

    return decorator


def after_hook(plugin_name: str) -> Callable:
    """Decorator factory that registers an after-hook for a plugin.

    The hook function receives (context, result) and can return a transformed result.
    """

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            return func(*args, **kwargs)

        _after_hooks[plugin_name].append(wrapper)
        return wrapper

    return decorator


# ============================================================================
# PluginManager
# ============================================================================

class PluginManager:
    """Discovers, loads, and executes plugins with dependency management."""

    def __init__(self):
        self._plugins: Dict[str, dict] = {}
        self._loaded: Set[str] = set()
        self._execution_order: List[str] = []

    def discover(self) -> None:
        """Collect all registered plugins and attach their hooks."""
        self._plugins = dict(_plugin_registry)

        # Attach hooks to their plugins
        for name, plugin_info in self._plugins.items():
            plugin_info["before_hooks"] = list(_before_hooks.get(name, []))
            plugin_info["after_hooks"] = list(_after_hooks.get(name, []))

        # Resolve execution order
        self._execution_order = self._topological_sort()

        print(f"Discovered {len(self._plugins)} plugins")

    def _topological_sort(self) -> List[str]:
        """Compute dependency-resolved execution order using topological sort."""
        # Build adjacency info
        in_degree: Dict[str, int] = {name: 0 for name in self._plugins}
        dependents: Dict[str, List[str]] = defaultdict(list)

        for name, info in self._plugins.items():
            for dep in info["depends_on"]:
                if dep not in self._plugins:
                    raise MissingDependencyError(
                        f"Plugin '{name}' depends on '{dep}', which is not registered. "
                        f"Available plugins: {sorted(self._plugins.keys())}"
                    )
                dependents[dep].append(name)
                in_degree[name] += 1

        # Kahn's algorithm
        queue = sorted([n for n, d in in_degree.items() if d == 0])
        order: List[str] = []

        while queue:
            node = queue.pop(0)
            order.append(node)

            for dependent in sorted(dependents[node]):
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)
                    queue.sort()  # Deterministic ordering

        if len(order) != len(self._plugins):
            # Find the cycle
            remaining = set(self._plugins.keys()) - set(order)
            raise CircularDependencyError(
                f"Circular dependency detected among plugins: {sorted(remaining)}"
            )

        return order

    def load(self, name: str) -> None:
        """Load a specific plugin (and its dependencies first)."""
        if name not in self._plugins:
            raise PluginNotFoundError(
                f"Plugin '{name}' not found. "
                f"Available: {sorted(self._plugins.keys())}"
            )

        if name in self._loaded:
            return

        # Load dependencies first
        for dep in self._plugins[name]["depends_on"]:
            self.load(dep)

        self._plugins[name]["loaded"] = True
        self._loaded.add(name)
        print(f"  Loaded plugin: {name} v{self._plugins[name]['version']}")

    def load_all(self) -> None:
        """Load all plugins in dependency order."""
        print("Loading plugins...")
        for name in self._execution_order:
            self.load(name)

    def unload(self, name: str) -> None:
        """Unload a plugin."""
        if name not in self._plugins:
            raise PluginNotFoundError(f"Plugin '{name}' not found")
        if name in self._loaded:
            self._plugins[name]["loaded"] = False
            self._loaded.discard(name)
            print(f"  Unloaded plugin: {name}")

    def execute(self, name: str, context: Dict[str, Any]) -> Any:
        """Execute a single plugin with its hooks."""
        if name not in self._plugins:
            raise PluginNotFoundError(f"Plugin '{name}' not found")

        info = self._plugins[name]

        if not info["loaded"]:
            raise PluginError(f"Plugin '{name}' is not loaded")

        # Run before hooks
        for hook in info["before_hooks"]:
            try:
                hook(context)
            except Exception as e:
                raise HookError(
                    f"Before hook '{hook.__name__}' for plugin '{name}' failed: {e}"
                ) from e

        # Run the plugin
        result = info["function"](context)

        # Run after hooks (can transform result)
        for hook in info["after_hooks"]:
            try:
                transformed = hook(context, result)
                if transformed is not None:
                    result = transformed
            except Exception as e:
                raise HookError(
                    f"After hook '{hook.__name__}' for plugin '{name}' failed: {e}"
                ) from e

        return result

    def execute_all(self, context: Dict[str, Any]) -> Dict[str, Any]:
        """Execute all loaded plugins in dependency order."""
        results: Dict[str, Any] = {}

        for name in self._execution_order:
            if name in self._loaded:
                results[name] = self.execute(name, context)

        return results

    def list_plugins(self) -> List[dict]:
        """Return metadata for all registered plugins."""
        return [
            {
                "name": info["name"],
                "version": info["version"],
                "depends_on": info["depends_on"],
                "loaded": info["loaded"],
                "doc": info["doc"],
                "before_hooks": len(info["before_hooks"]),
                "after_hooks": len(info["after_hooks"]),
            }
            for info in sorted(self._plugins.values(), key=lambda x: x["name"])
        ]

    def get_execution_order(self) -> List[str]:
        """Return plugin names in dependency-resolved order."""
        return list(self._execution_order)

    def __repr__(self) -> str:
        return (
            f"PluginManager(plugins={len(self._plugins)}, "
            f"loaded={len(self._loaded)})"
        )


# ============================================================================
# Demo: Register plugins and hooks
# ============================================================================

@plugin(name="core", version="1.0.0")
def core_plugin(context: Dict[str, Any]) -> str:
    """Core plugin that initializes the system."""
    context["initialized"] = True
    return "Core initialized"


@plugin(name="auth", version="1.0.0", depends_on=["core"])
def auth_plugin(context: Dict[str, Any]) -> str:
    """Authentication plugin."""
    return f"Authenticated user: {context.get('user', 'anonymous')}"


@plugin(name="data_loader", version="2.1.0", depends_on=["core"])
def data_loader_plugin(context: Dict[str, Any]) -> Dict[str, Any]:
    """Load data from source."""
    return {"records": 100, "source": context.get("source", "default")}


@plugin(name="transformer", version="1.2.0", depends_on=["data_loader"])
def transformer_plugin(context: Dict[str, Any]) -> str:
    """Transform loaded data."""
    return "Data transformed"


@plugin(name="reporter", version="1.0.0", depends_on=["transformer", "auth"])
def reporter_plugin(context: Dict[str, Any]) -> str:
    """Generate report."""
    return f"Report for {context.get('user', 'anonymous')}"


# Register hooks
@before_hook("auth")
def check_credentials(context: Dict[str, Any]) -> None:
    """Ensure user exists in context."""
    if "user" not in context:
        context["user"] = "guest"
    print(f"  [HOOK] Checking credentials for: {context['user']}")


@before_hook("core")
def validate_context(context: Dict[str, Any]) -> None:
    """Validate that context is a dict."""
    if not isinstance(context, dict):
        raise ValueError("Context must be a dict")
    print("  [HOOK] Context validated")


@after_hook("reporter")
def format_report(context: Dict[str, Any], result: str) -> str:
    """Format the report output."""
    formatted = f"=== {result} ==="
    print(f"  [HOOK] Formatted report: {formatted}")
    return formatted


@after_hook("data_loader")
def log_data_stats(context: Dict[str, Any], result: Dict) -> None:
    """Log data loading statistics."""
    if isinstance(result, dict):
        print(f"  [HOOK] Loaded {result.get('records', '?')} records from {result.get('source', '?')}")
    # Return None = don't transform result


# ============================================================================
# Main Demo
# ============================================================================

if __name__ == "__main__":
    print("=" * 60)
    print("PLUGIN SYSTEM DEMO")
    print("=" * 60)

    # Create manager and discover plugins
    manager = PluginManager()
    manager.discover()

    # Show plugin info
    print("\n=== Registered Plugins ===")
    for info in manager.list_plugins():
        deps = ", ".join(info["depends_on"]) if info["depends_on"] else "none"
        print(
            f"  {info['name']} v{info['version']} "
            f"(deps: {deps}, hooks: {info['before_hooks']}B/{info['after_hooks']}A)"
        )

    # Show execution order
    print(f"\n=== Execution Order ===")
    print(f"  {manager.get_execution_order()}")

    # Load all plugins
    print(f"\n=== Loading ===")
    manager.load_all()

    # Execute all plugins
    print(f"\n=== Executing All Plugins ===")
    context = {"user": "alice", "source": "database"}
    results = manager.execute_all(context)

    print(f"\n=== Results ===")
    for name, result in results.items():
        print(f"  {name}: {result}")

    # Execute single plugin
    print(f"\n=== Execute Single Plugin ===")
    result = manager.execute("auth", {"user": "bob"})
    print(f"  auth result: {result}")

    # Unload a plugin
    print(f"\n=== Unload ===")
    manager.unload("reporter")
    print(f"  Loaded plugins: {sorted(manager._loaded)}")

    # Test circular dependency detection
    print(f"\n=== Circular Dependency Test ===")
    # Save state
    saved = dict(_plugin_registry)

    @plugin(name="cycle_a", version="1.0.0", depends_on=["cycle_b"])
    def cycle_a(ctx):
        return "A"

    @plugin(name="cycle_b", version="1.0.0", depends_on=["cycle_a"])
    def cycle_b(ctx):
        return "B"

    bad_manager = PluginManager()
    try:
        bad_manager.discover()
    except CircularDependencyError as e:
        print(f"  Caught: {e}")

    # Restore state
    _plugin_registry.clear()
    _plugin_registry.update(saved)

    # Test missing dependency
    print(f"\n=== Missing Dependency Test ===")

    @plugin(name="orphan", version="1.0.0", depends_on=["nonexistent"])
    def orphan_plugin(ctx):
        return "orphan"

    bad_manager2 = PluginManager()
    try:
        bad_manager2.discover()
    except MissingDependencyError as e:
        print(f"  Caught: {e}")

    print(f"\n=== Done ===")
