# Week 4: Solutions

## Exercise 1 Solution: Basic Annotations

```python
from typing import Optional, List, Dict, Any

# int + int -> int; arithmetic addition
def add(a: int, b: int) -> int:
    return a + b

# int -> bool; parity check
def is_even(n: int) -> bool:
    return n % 2 == 0

# str + bool -> str; string formatting
def greet(name: str, excited: bool = False) -> str:
    suffix = "!" if excited else "."
    return f"Hello, {name}{suffix}"

# List of any -> Optional; may return None when empty
def first_or_none(items: List[Any]) -> Optional[Any]:
    return items[0] if items else None

# str + int -> str; string repetition
def repeat(text: str, times: int) -> str:
    return text * times

# float -> float; temperature conversion (division always yields float)
def celsius_to_fahrenheit(c: float) -> float:
    return c * 9 / 5 + 32

# str -> int; counting produces an integer
def count_words(sentence: str) -> int:
    return len(sentence.split())

# two dicts -> merged dict; generic key-value merge
def merge_dicts(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:
    result = {**a, **b}
    return result

# float bounds check -> float; all three must be same numeric type
def clamp(value: float, minimum: float, maximum: float) -> float:
    return max(minimum, min(value, maximum))

# str -> Optional[bool]; may return None for unrecognized input
def parse_bool(text: str) -> Optional[bool]:
    if text.lower() in ("true", "1", "yes", "on"):
        return True
    elif text.lower() in ("false", "0", "no", "off"):
        return False
    return None


# Usage examples
if __name__ == "__main__":
    print(add(3, 4))                          # 7
    print(is_even(4))                         # True
    print(greet("Alice", excited=True))       # Hello, Alice!
    print(first_or_none([]))                  # None
    print(first_or_none([10, 20]))            # 10
    print(repeat("ha", 3))                    # hahaha
    print(celsius_to_fahrenheit(100.0))       # 212.0
    print(count_words("the quick brown fox")) # 4
    print(merge_dicts({"a": 1}, {"b": 2}))   # {'a': 1, 'b': 2}
    print(clamp(15.0, 0.0, 10.0))            # 10.0
    print(parse_bool("yes"))                  # True
    print(parse_bool("maybe"))               # None
