## Exercise 2 Solution: Collection Types

```python
from typing import List, Dict, Tuple, Set, Sequence, Mapping, Any, TypeVar

T = TypeVar("T")


def invert_index(index: Dict[str, List[int]]) -> Dict[int, List[str]]:
    """Given a word -> [doc_ids] index, return a doc_id -> [words] index."""
    result: Dict[int, List[str]] = {}
    for word, doc_ids in index.items():
        for doc_id in doc_ids:
            if doc_id not in result:
                result[doc_id] = []
            result[doc_id].append(word)
    return result


def flatten_scores(
    nested: Dict[str, List[Tuple[int, str]]]
) -> List[Tuple[str, int, str]]:
    """Flatten nested scores into (category, score, label) tuples."""
    result: List[Tuple[str, int, str]] = []
    for category, entries in nested.items():
        for score, label in entries:
            result.append((category, score, label))
    return result


def group_by_key(pairs: List[Tuple[str, int]]) -> Dict[str, List[int]]:
    """Group a list of (key, value) pairs into a dict of key -> [values]."""
    result: Dict[str, List[int]] = {}
    for key, value in pairs:
        if key not in result:
            result[key] = []
        result[key].append(value)
    return result


def unique_values(mapping: Mapping[str, Sequence[int]]) -> Set[int]:
    """Return the set of all unique values across all lists in the mapping."""
    result: Set[int] = set()
    for values in mapping.values():
        result.update(values)
    return result


def merge_sorted(lists: List[List[int]]) -> List[int]:
    """Merge multiple sorted lists into one sorted list."""
    result: List[int] = []
    for lst in lists:
        result.extend(lst)
    result.sort()
    return result


def deep_get(data: Dict[str, Any], path: str, default: Any) -> Any:
    """Navigate nested dicts using a dot-separated path string."""
    keys = path.split(".")
    current: Any = data
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


# Usage examples
if __name__ == "__main__":
    # invert_index
    idx = {"python": [1, 2], "java": [2, 3]}
    print(invert_index(idx))
    # {1: ['python'], 2: ['python', 'java'], 3: ['java']}

    # flatten_scores
    scores = {"math": [(95, "A"), (87, "B+")], "science": [(91, "A-")]}
