    # group_by_key
    pairs = [("a", 1), ("b", 2), ("a", 3)]
    print(group_by_key(pairs))
    # {'a': [1, 3], 'b': [2]}

    # unique_values
    mapping = {"x": [1, 2, 3], "y": [2, 3, 4]}
    print(unique_values(mapping))
    # {1, 2, 3, 4}

    # merge_sorted
    print(merge_sorted([[1, 3, 5], [2, 4, 6], [0, 7]]))
    # [0, 1, 2, 3, 4, 5, 6, 7]

    # deep_get
    data = {"a": {"b": {"c": 42}}}
    print(deep_get(data, "a.b.c", 0))   # 42
    print(deep_get(data, "a.x.y", -1))  # -1
