## Exercise 4 Solution: Generics, Stack[T]

```python
from typing import TypeVar, Generic, List, Iterator, Callable, Any

T = TypeVar("T")
U = TypeVar("U")


class Stack(Generic[T]):
    """A generic LIFO stack."""

    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        """Push an item onto the top of the stack."""
        self._items.append(item)

    def pop(self) -> T:
        """Remove and return the top item. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        """Return the top item without removing it. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError("peek at empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        """Return True if the stack has no items."""
        return len(self._items) == 0

    def size(self) -> int:
        """Return the number of items in the stack."""
        return len(self._items)

    def clear(self) -> None:
        """Remove all items from the stack."""
        self._items.clear()

    def to_list(self) -> List[T]:
        """Return items as a list in bottom-to-top order."""
        return list(self._items)

    def __iter__(self) -> Iterator[T]:
        """Iterate from top to bottom."""
        return reversed(self._items).__iter__()

    def __len__(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        items_str = ", ".join(repr(item) for item in self._items)
        return f"Stack([{items_str}])"

    def map(self, fn: Callable[[T], U]) -> "Stack[U]":
        """Return a new stack with fn applied to each item."""
        new_stack: Stack[U] = Stack()
        for item in self._items:
            new_stack.push(fn(item))
        return new_stack

    def filter(self, fn: Callable[[T], bool]) -> "Stack[T]":
        """Return a new stack keeping only items where fn returns True."""
        new_stack: Stack[T] = Stack()
        for item in self._items:
            if fn(item):
                new_stack.push(item)
        return new_stack


# Bounded generic for comparable types
class _ComparableBase:
    """Mixin that ensures __lt__ exists for type-checking purposes."""
    def __lt__(self, other: Any) -> bool: ...


Comparable = TypeVar("Comparable", int, float, str)


class SortedStack(Generic[Comparable]):
    """A stack that maintains sorted order (smallest on top)."""

    def __init__(self) -> None:
        self._items: List[Comparable] = []

    def push(self, item: Comparable) -> None:
        """Insert item in sorted position (smallest first)."""
        # Find insertion point using binary search logic
        idx = 0
        for i, existing in enumerate(self._items):
            if item < existing:
                idx = i
                break
            idx = i + 1
        self._items.insert(idx, item)

    def pop(self) -> Comparable:
        """Remove and return the smallest item."""
        if not self._items:
            raise IndexError("pop from empty sorted stack")
        return self._items.pop(0)

    def peek(self) -> Comparable:
        """Return the smallest item without removing it."""
        if not self._items:
            raise IndexError("peek at empty sorted stack")
        return self._items[0]

    def to_list(self) -> List[Comparable]:
        """Return items in sorted order."""
        return list(self._items)

    def is_empty(self) -> bool:
        return len(self._items) == 0

    def size(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        return f"SortedStack({self._items!r})"


# Usage examples
if __name__ == "__main__":
    # Generic Stack
    print("=== Stack[int] ===")
    s: Stack[int] = Stack()
    s.push(10)
    s.push(20)
    s.push(30)
    print(s)                        # Stack([10, 20, 30])
    print(f"peek: {s.peek()}")      # 30
    print(f"pop: {s.pop()}")        # 30
    print(f"size: {s.size()}")      # 2
    print(f"list: {s.to_list()}")   # [10, 20]

    # Iteration (top to bottom)
