from typing import Protocol, runtime_checkable, Any, List, Dict, ClassVar
from dataclasses import dataclass


@runtime_checkable
class Printable(Protocol):
    """Any object that can represent itself as a human-readable string."""
    def to_string(self) -> str: ...


@runtime_checkable
class Comparable(Protocol):
    """Any object that supports less-than comparison."""
    def __lt__(self, other: Any) -> bool: ...


@runtime_checkable
class Serializable(Protocol):
    """Any object that can be converted to/from a dict."""
    def to_dict(self) -> Dict[str, Any]: ...

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Serializable": ...


# --- Unrelated classes that satisfy protocols ---

class Product:
    """Satisfies: Printable, Comparable, Serializable (all three)."""

    def __init__(self, name: str, price: float, sku: str) -> None:
        self.name = name
        self.price = price
        self.sku = sku

    def to_string(self) -> str:
        return f"{self.name} (${self.price:.2f}) [{self.sku}]"

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, Product):
            return self.price < other.price
        return NotImplemented

    def to_dict(self) -> Dict[str, Any]:
        return {"name": self.name, "price": self.price, "sku": self.sku}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Product":
        return cls(name=data["name"], price=data["price"], sku=data["sku"])

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Product):
            return self.name == other.name and self.price == other.price and self.sku == other.sku
        return NotImplemented

    def __repr__(self) -> str:
        return f"Product({self.name!r}, {self.price}, {self.sku!r})"


class LogEntry:
    """Satisfies: Printable, Comparable."""

    def __init__(self, timestamp: float, level: str, message: str) -> None:
        self.timestamp = timestamp
        self.level = level
        self.message = message

    def to_string(self) -> str:
        return f"[{self.timestamp:.3f}] {self.level}: {self.message}"

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, LogEntry):
            return self.timestamp < other.timestamp
        return NotImplemented

    def __repr__(self) -> str:
        return f"LogEntry({self.timestamp}, {self.level!r}, {self.message!r})"


class Coordinate:
    """Satisfies: Printable, Serializable."""

    def __init__(self, x: float, y: float, label: str = "") -> None:
        self.x = x
        self.y = y
        self.label = label

    def to_string(self) -> str:
        name = f" '{self.label}'" if self.label else ""
        return f"({self.x}, {self.y}){name}"

    def to_dict(self) -> Dict[str, Any]:
        return {"x": self.x, "y": self.y, "label": self.label}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Coordinate":
        return cls(x=data["x"], y=data["y"], label=data.get("label", ""))

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Coordinate):
            return self.x == other.x and self.y == other.y and self.label == other.label
        return NotImplemented

    def __repr__(self) -> str:
        return f"Coordinate({self.x}, {self.y}, {self.label!r})"


# --- Functions that accept protocol types ---

def display_all(items: List[Printable]) -> None:
    """Print each item using to_string()."""
    for item in items:
        print(item.to_string())


def sort_items(items: List[Comparable]) -> List[Comparable]:
    """Sort items using their __lt__ method."""
    return sorted(items)


def round_trip(obj: Serializable) -> bool:
    """Serialize to dict and back. Returns True if round-trip preserves equality."""
    data = obj.to_dict()
    restored = type(obj).from_dict(data)
    return obj == restored


# Usage examples
