## Exercise 6 Solution: Runtime Validation with Annotations

```python
from dataclasses import dataclass, fields, field
from typing import get_type_hints, Any, Dict, List, Optional, Union, Tuple
import json
import os
import typing
import functools


def _check_type(value: Any, expected_type: Any, field_name: str) -> None:
    """Recursively check that value matches expected_type."""
    # Handle None/NoneType
    if expected_type is type(None):
        if value is not None:
            raise TypeError(
                f"Field '{field_name}' expected None, "
                f"got {type(value).__name__}: {value!r}"
            )
        return

    # Handle Optional and Union
    origin = getattr(expected_type, "__origin__", None)
    args = getattr(expected_type, "__args__", ())

    if origin is Union:
        # Union[X, Y, ...]: value must match at least one
        errors = []
        for arg in args:
            try:
                _check_type(value, arg, field_name)
                return  # Matched one of the union members
            except TypeError as e:
                errors.append(str(e))
        raise TypeError(
            f"Field '{field_name}' expected {expected_type}, "
            f"got {type(value).__name__}: {value!r}"
        )

    # Handle List[X]
    if origin is list:
        if not isinstance(value, list):
            raise TypeError(
                f"Field '{field_name}' expected list, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args:
            elem_type = args[0]
            for i, item in enumerate(value):
                _check_type(item, elem_type, f"{field_name}[{i}]")
        return

    # Handle Dict[K, V]
    if origin is dict:
        if not isinstance(value, dict):
            raise TypeError(
                f"Field '{field_name}' expected dict, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args and len(args) == 2:
            key_type, val_type = args
            for k, v in value.items():
                _check_type(k, key_type, f"{field_name}.key({k!r})")
                _check_type(v, val_type, f"{field_name}[{k!r}]")
        return

    # Handle Tuple[X, ...]
    if origin is tuple:
        if not isinstance(value, tuple):
            raise TypeError(
                f"Field '{field_name}' expected tuple, "
                f"got {type(value).__name__}: {value!r}"
            )
        if args:
            for i, (item, item_type) in enumerate(zip(value, args)):
                _check_type(item, item_type, f"{field_name}[{i}]")
        return

    # Handle basic types
    if isinstance(expected_type, type):
        if not isinstance(value, expected_type):
            raise TypeError(
                f"Field '{field_name}' expected {expected_type.__name__}, "
                f"got {type(value).__name__}: {value!r}"
            )
        return


def validate(cls: type) -> type:
    """Class decorator that wraps __init__ to validate types at construction."""
    original_init = cls.__init__
    hints = get_type_hints(cls)

    @functools.wraps(original_init)
    def validated_init(self: Any, *args: Any, **kwargs: Any) -> None:
        original_init(self, *args, **kwargs)
        for field_name, expected_type in hints.items():
            if not hasattr(self, field_name):
                continue
            value = getattr(self, field_name)
            if value is None:
                # Check if None is allowed
                origin = getattr(expected_type, "__origin__", None)
                type_args = getattr(expected_type, "__args__", ())
                is_optional = (
                    origin is Union
                    and type(None) in type_args
                )
                if not is_optional and expected_type is not type(None):
                    raise TypeError(
                        f"Field '{field_name}' expected {expected_type}, "
                        f"got None"
                    )
            else:
                _check_type(value, expected_type, field_name)

    cls.__init__ = validated_init
    return cls


@validate
@dataclass
class DatabaseConfig:
    host: str
    port: int
    name: str
    pool_size: int = 5
    ssl: bool = False


@validate
@dataclass
class ServerConfig:
    host: str
    port: int
    debug: bool = False
    allowed_origins: Optional[List[str]] = None
    max_connections: int = 100


@validate
@dataclass
class AppConfig:
    database: DatabaseConfig
    server: ServerConfig
    app_name: str
    version: str
    features: Optional[Dict[str, bool]] = None


def parse_config(data: Dict[str, Any]) -> AppConfig:
    """Parse a raw dict into a fully typed AppConfig with nested configs."""
    db_data = data.get("database", {})
    server_data = data.get("server", {})

    database = DatabaseConfig(
        host=db_data.get("host", "localhost"),
        port=db_data.get("port", 5432),
        name=db_data.get("name", "mydb"),
        pool_size=db_data.get("pool_size", 5),
        ssl=db_data.get("ssl", False),
    )

    server = ServerConfig(
        host=server_data.get("host", "0.0.0.0"),
        port=server_data.get("port", 8080),
        debug=server_data.get("debug", False),
        allowed_origins=server_data.get("allowed_origins"),
        max_connections=server_data.get("max_connections", 100),
    )

    return AppConfig(
        database=database,
        server=server,
        app_name=data.get("app_name", "myapp"),
        version=data.get("version", "0.1.0"),
        features=data.get("features"),
    )


def _coerce_value(raw: str, target_type: type) -> Any:
    """Coerce a string value to the target type."""
    if target_type is bool:
        return raw.lower() in ("true", "1", "yes", "on")
    if target_type is int:
        return int(raw)
    if target_type is float:
        return float(raw)
    return raw


def load_config(
    json_path: Optional[str] = None, env_prefix: str = "APP"
) -> AppConfig:
    """Load config with priority: env vars > JSON file > defaults."""
    # Start with defaults
    data: Dict[str, Any] = {
        "database": {
            "host": "localhost",
            "port": 5432,
            "name": "mydb",
            "pool_size": 5,
            "ssl": False,
        },
        "server": {
            "host": "0.0.0.0",
            "port": 8080,
            "debug": False,
            "allowed_origins": None,
            "max_connections": 100,
        },
        "app_name": "myapp",
        "version": "0.1.0",
        "features": None,
    }

    # Layer 2: JSON file
    if json_path and os.path.exists(json_path):
        with open(json_path, "r") as f:
            json_data = json.load(f)
        # Deep merge
        for key, value in json_data.items():
            if isinstance(value, dict) and key in data and isinstance(data[key], dict):
                data[key].update(value)
            else:
                data[key] = value

    # Layer 3: Environment variables
    env_mapping: Dict[str, Tuple[str, str, type]] = {
        f"{env_prefix}_DATABASE_HOST": ("database", "host", str),
        f"{env_prefix}_DATABASE_PORT": ("database", "port", int),
        f"{env_prefix}_DATABASE_NAME": ("database", "name", str),
        f"{env_prefix}_DATABASE_POOL_SIZE": ("database", "pool_size", int),
        f"{env_prefix}_DATABASE_SSL": ("database", "ssl", bool),
        f"{env_prefix}_SERVER_HOST": ("server", "host", str),
        f"{env_prefix}_SERVER_PORT": ("server", "port", int),
        f"{env_prefix}_SERVER_DEBUG": ("server", "debug", bool),
        f"{env_prefix}_SERVER_MAX_CONNECTIONS": ("server", "max_connections", int),
        f"{env_prefix}_APP_NAME": (None, "app_name", str),
        f"{env_prefix}_VERSION": (None, "version", str),
        f"{env_prefix}_DEBUG": ("server", "debug", bool),
    }

    for env_key, (section, field_name, target_type) in env_mapping.items():
        raw = os.environ.get(env_key)
        if raw is not None:
            value = _coerce_value(raw, target_type)
            if section:
                data[section][field_name] = value
            else:
                data[field_name] = value

    return parse_config(data)


# Usage examples
if __name__ == "__main__":
