## Mini-Project Solution: Type-Safe Config Engine

```python
"""
Type-Safe Config Engine
=======================
A complete configuration system using dataclasses, generics, protocols,
and runtime validation. Reads from env vars, JSON files, and CLI args
with priority ordering.
"""

from __future__ import annotations

import functools
import json
import os
import sys
import typing
from dataclasses import dataclass, fields, field, asdict
from typing import (
    Any, Callable, Dict, Generic, List, Optional, Protocol,
    Sequence, Tuple, Type, TypeVar, Union, get_type_hints,
)


# ============================================================================
# Runtime Type Validation
# ============================================================================

def _check_type(value: Any, expected: Any, name: str) -> None:
    """Recursively validate that value matches the expected type annotation."""
    if expected is type(None):
        if value is not None:
            raise TypeError(f"Field '{name}' expected None, got {type(value).__name__}: {value!r}")
        return

    origin = getattr(expected, "__origin__", None)
    args = getattr(expected, "__args__", ())

    # Union / Optional
    if origin is Union:
        for arg in args:
            try:
                _check_type(value, arg, name)
                return
            except TypeError:
                pass
        raise TypeError(
            f"Field '{name}' expected {expected}, got {type(value).__name__}: {value!r}"
        )

    # List[X]
    if origin is list:
        if not isinstance(value, list):
            raise TypeError(f"Field '{name}' expected list, got {type(value).__name__}: {value!r}")
        if args:
            for i, item in enumerate(value):
                _check_type(item, args[0], f"{name}[{i}]")
        return

    # Dict[K, V]
    if origin is dict:
        if not isinstance(value, dict):
            raise TypeError(f"Field '{name}' expected dict, got {type(value).__name__}: {value!r}")
        if args and len(args) == 2:
            for k, v in value.items():
                _check_type(k, args[0], f"{name}.key({k!r})")
                _check_type(v, args[1], f"{name}[{k!r}]")
        return

    # Dataclass (nested config)
    if isinstance(expected, type) and hasattr(expected, "__dataclass_fields__"):
        if not isinstance(value, expected):
            raise TypeError(
                f"Field '{name}' expected {expected.__name__}, "
                f"got {type(value).__name__}: {value!r}"
            )
        return

    # Basic types
    if isinstance(expected, type):
        if not isinstance(value, expected):
            raise TypeError(
                f"Field '{name}' expected {expected.__name__}, "
                f"got {type(value).__name__}: {value!r}"
            )


def validate(cls: type) -> type:
    """Decorator: wraps __init__ to validate all fields match their type hints."""
    original_init = cls.__init__
    hints = get_type_hints(cls)

    @functools.wraps(original_init)
    def checked_init(self: Any, *args: Any, **kwargs: Any) -> None:
        original_init(self, *args, **kwargs)
        for fname, ftype in hints.items():
            if not hasattr(self, fname):
                continue
            val = getattr(self, fname)
            if val is None:
                origin = getattr(ftype, "__origin__", None)
                fargs = getattr(ftype, "__args__", ())
                is_optional = origin is Union and type(None) in fargs
                if not is_optional:
                    raise TypeError(f"Field '{fname}' is not Optional but got None")
            else:
                _check_type(val, ftype, fname)

    cls.__init__ = checked_init
    return cls


# ============================================================================
# Config Dataclasses
# ============================================================================

@validate
@dataclass
class DatabaseConfig:
    host: str
    port: int
    name: str
    pool_size: int = 5
    ssl: bool = False
    timeout: float = 30.0


@validate
@dataclass
class LoggingConfig:
    level: str = "INFO"
    format: str = "json"
    file: Optional[str] = None


@validate
@dataclass
class AppConfig:
    database: DatabaseConfig
    logging: LoggingConfig
    app_name: str = "myapp"
    version: str = "0.1.0"
    debug: bool = False
    tags: Optional[List[str]] = None

    def __post_init__(self) -> None:
        if self.tags is None:
            object.__setattr__(self, "tags", [])


# ============================================================================
# ConfigSource Protocol and Implementations
# ============================================================================

class ConfigSource(Protocol):
    """Protocol for configuration sources."""
    name: str
    priority: int
    def read(self) -> Dict[str, Any]: ...


class JsonFileSource:
    """Reads config from a JSON file."""

    def __init__(self, path: str, priority: int = 1) -> None:
        self.name = f"json:{path}"
        self.priority = priority
        self._path = path

    def read(self) -> Dict[str, Any]:
        if not os.path.exists(self._path):
            return {}
        with open(self._path, "r") as f:
            return json.load(f)


class EnvSource:
    """Reads config from environment variables with a prefix."""

    ENV_MAP: Dict[str, Tuple[List[str], type]] = {
        "DATABASE_HOST": (["database", "host"], str),
        "DATABASE_PORT": (["database", "port"], int),
        "DATABASE_NAME": (["database", "name"], str),
        "DATABASE_POOL_SIZE": (["database", "pool_size"], int),
        "DATABASE_SSL": (["database", "ssl"], bool),
        "DATABASE_TIMEOUT": (["database", "timeout"], float),
        "LOGGING_LEVEL": (["logging", "level"], str),
        "LOGGING_FORMAT": (["logging", "format"], str),
        "LOGGING_FILE": (["logging", "file"], str),
        "APP_NAME": (["app_name"], str),
        "VERSION": (["version"], str),
        "DEBUG": (["debug"], bool),
        "TAGS": (["tags"], list),
    }

    def __init__(self, prefix: str = "APP", priority: int = 2) -> None:
        self.name = f"env:{prefix}_*"
        self.priority = priority
        self._prefix = prefix

    def read(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for suffix, (path, target_type) in self.ENV_MAP.items():
            env_key = f"{self._prefix}_{suffix}"
            raw = os.environ.get(env_key)
            if raw is None:
                continue
            value = self._coerce(raw, target_type)
            self._set_nested(result, path, value)
        return result

    @staticmethod
    def _coerce(raw: str, target: type) -> Any:
        if target is bool:
            return raw.lower() in ("true", "1", "yes", "on")
        if target is int:
            return int(raw)
        if target is float:
            return float(raw)
        if target is list:
            try:
                parsed = json.loads(raw)
                if isinstance(parsed, list):
                    return parsed
            except json.JSONDecodeError:
                pass
            return [s.strip() for s in raw.split(",") if s.strip()]
        return raw

    @staticmethod
    def _set_nested(d: Dict[str, Any], path: List[str], value: Any) -> None:
        for key in path[:-1]:
            if key not in d:
                d[key] = {}
            d = d[key]
        d[path[-1]] = value


class CliSource:
    """Reads config from --key=value command-line arguments."""

    def __init__(self, argv: Optional[List[str]] = None, priority: int = 3) -> None:
        self.name = "cli"
        self.priority = priority
        self._argv = argv if argv is not None else sys.argv[1:]

    def read(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for arg in self._argv:
            if not arg.startswith("--") or "=" not in arg:
                continue
            key, raw_value = arg[2:].split("=", 1)
            # Convert --database-host to database.host
            path = key.replace("-", "_").split(".")
            if len(path) == 1:
                # Try splitting on underscore for nested: database_host -> database.host
                parts = path[0].split("_", 1)
                if len(parts) == 2 and parts[0] in ("database", "logging", "server"):
                    path = parts
            value = self._auto_coerce(raw_value)
            self._set_nested(result, path, value)
        return result

    @staticmethod
    def _auto_coerce(raw: str) -> Any:
        if raw.lower() in ("true", "yes"):
            return True
        if raw.lower() in ("false", "no"):
            return False
        try:
            return int(raw)
        except ValueError:
            pass
        try:
            return float(raw)
        except ValueError:
            pass
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, (list, dict)):
                return parsed
        except json.JSONDecodeError:
            pass
        return raw

    @staticmethod
    def _set_nested(d: Dict[str, Any], path: List[str], value: Any) -> None:
        for key in path[:-1]:
            if key not in d:
                d[key] = {}
            d = d[key]
        d[path[-1]] = value


# ============================================================================
# Generic ConfigStore
# ============================================================================

T = TypeVar("T")


class ConfigStore(Generic[T]):
    """Generic store that loads, validates, and manages typed configuration."""

    def __init__(self, config_cls: Type[T], sources: Optional[List[Any]] = None) -> None:
        self._config_cls = config_cls
        self._sources: List[Any] = sorted(sources or [], key=lambda s: s.priority)
        self._config: Optional[T] = None

    def load(self, sources: Optional[List[Any]] = None) -> T:
        """Merge all sources in priority order and construct a validated config."""
        if sources is not None:
            self._sources = sorted(sources, key=lambda s: s.priority)

        merged: Dict[str, Any] = {}
        for source in self._sources:
            data = source.read()
            self._deep_merge(merged, data)

        self._config = self._build(self._config_cls, merged)
        return self._config

    def get(self) -> T:
        """Return the current config. Raises if not loaded."""
        if self._config is None:
            raise RuntimeError("Config not loaded. Call load() first.")
        return self._config

    def reload(self) -> T:
        """Re-read all sources and return fresh config."""
        return self.load()

    def diff(self, other: T) -> Dict[str, Tuple[Any, Any]]:
        """Return dict of {field: (old_value, new_value)} for changed fields."""
        if self._config is None:
            raise RuntimeError("Config not loaded. Call load() first.")
        current_dict = self._flatten(asdict(self._config))
        other_dict = self._flatten(asdict(other))
        changes: Dict[str, Tuple[Any, Any]] = {}
        all_keys = set(current_dict) | set(other_dict)
        for key in all_keys:
            old = current_dict.get(key)
            new = other_dict.get(key)
            if old != new:
                changes[key] = (old, new)
        return changes

    def to_dict(self) -> Dict[str, Any]:
        """Serialize current config to a dict."""
        if self._config is None:
            raise RuntimeError("Config not loaded. Call load() first.")
        return asdict(self._config)

    def to_json(self, indent: int = 2) -> str:
        """Serialize current config to a JSON string."""
        return json.dumps(self.to_dict(), indent=indent)

    # --- Internal helpers ---

    @staticmethod
    def _deep_merge(base: Dict[str, Any], override: Dict[str, Any]) -> None:
        """Merge override into base, recursing into nested dicts."""
        for key, value in override.items():
            if (
                key in base
                and isinstance(base[key], dict)
                and isinstance(value, dict)
            ):
                ConfigStore._deep_merge(base[key], value)
            else:
                base[key] = value

    @classmethod
    def _build(cls, config_cls: Type, data: Dict[str, Any]) -> Any:
        """Recursively construct a dataclass from a nested dict."""
        if not hasattr(config_cls, "__dataclass_fields__"):
            return data

        hints = get_type_hints(config_cls)
        kwargs: Dict[str, Any] = {}

        for f in fields(config_cls):
            if f.name not in data:
                continue
            value = data[f.name]
            ftype = hints.get(f.name, type(value))

            # If the field type is a dataclass and value is a dict, recurse
            actual_type = ftype
            # Unwrap Optional[X] to get X
            origin = getattr(ftype, "__origin__", None)
            ftype_args = getattr(ftype, "__args__", ())
            if origin is Union and len(ftype_args) == 2 and type(None) in ftype_args:
                actual_type = [a for a in ftype_args if a is not type(None)][0]

            if (
                isinstance(value, dict)
                and isinstance(actual_type, type)
                and hasattr(actual_type, "__dataclass_fields__")
            ):
                kwargs[f.name] = cls._build(actual_type, value)
            else:
                kwargs[f.name] = value

        return config_cls(**kwargs)

    @staticmethod
    def _flatten(d: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
        """Flatten a nested dict into dot-separated keys."""
        result: Dict[str, Any] = {}
        for key, value in d.items():
            full_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                result.update(ConfigStore._flatten(value, full_key))
            else:
                result[full_key] = value
        return result


# ============================================================================
# Main
# ============================================================================

def main() -> None:
    """Demonstrate the config engine."""
    # Define sources
    sources = [
        JsonFileSource("config.json", priority=1),
        EnvSource(prefix="APP", priority=2),
        CliSource(priority=3),
    ]

    # Create store
    store: ConfigStore[AppConfig] = ConfigStore(AppConfig, sources)

    print("Loading configuration...")
    for src in sources:
        print(f"  Source: {src.name} (priority {src.priority})")

    try:
        config = store.load()
    except (TypeError, KeyError, ValueError) as e:
        print(f"\nConfiguration error: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"\nResolved configuration:")
    print(f"  {config!r}")

    # Count annotated fields
    def count_fields(cls: type) -> int:
        total = 0
        for f in fields(cls):
            ftype = get_type_hints(cls).get(f.name)
            origin = getattr(ftype, "__origin__", None)
            fargs = getattr(ftype, "__args__", ())
            actual = ftype
            if origin is Union and len(fargs) == 2 and type(None) in fargs:
                actual = [a for a in fargs if a is not type(None)][0]
            if isinstance(actual, type) and hasattr(actual, "__dataclass_fields__"):
                total += count_fields(actual)
            else:
                total += 1
        return total

    total = count_fields(AppConfig)
    print(f"\nValidation: PASSED (all fields match declared types)")
    print(f"Type coverage: {total}/{total} fields annotated (100%)")

    # Show JSON
    print(f"\nJSON output:")
    print(store.to_json(indent=2))


if __name__ == "__main__":
    main()
