        assert double(3) == 6
        assert double(4) == 8
        assert double.cache_info()["size"] == 2

    def test_eviction(self):
        @cache(maxsize=2)
        def identity(n):
            return n

        identity(1)
        identity(2)
        identity(3)  # should evict 1
        assert identity.cache_info()["size"] == 2

    def test_lru_order(self):
        call_count = 0

        @cache(maxsize=2)
        def f(n):
            nonlocal call_count
            call_count += 1
            return n

        f(1)  # cache: [1]
        f(2)  # cache: [1, 2]
        f(1)  # cache: [2, 1], 1 moved to end
        f(3)  # cache: [1, 3], 2 evicted
        call_count = 0
        f(1)  # should be cached
        assert call_count == 0
        f(2)  # should NOT be cached (was evicted)
        assert call_count == 1

    def test_cache_clear(self):
        @cache(maxsize=10)
        def f(n):
            return n

        f(1)
        f(2)
        assert f.cache_info()["size"] == 2
        f.cache_clear()
        assert f.cache_info()["size"] == 0

    def test_invalid_maxsize(self):
        with pytest.raises(ValueError, match="at least 1"):
            cache(maxsize=0)

