from py_skool.closures import make_counter, make_multiplier, compose, memoize


#: make_counter --


class TestMakeCounter:
    def test_initial_value_default(self):
        c = make_counter()
        assert c["get"]() == 0

    def test_initial_value_custom(self):
        c = make_counter(10)
        assert c["get"]() == 10

    def test_increment(self):
        c = make_counter(0)
        assert c["increment"]() == 1
        assert c["increment"]() == 2
        assert c["increment"]() == 3

    def test_decrement(self):
        c = make_counter(5)
        assert c["decrement"]() == 4
        assert c["decrement"]() == 3

    def test_increment_and_decrement(self):
        c = make_counter(0)
        c["increment"]()
        c["increment"]()
        c["decrement"]()
        assert c["get"]() == 1

    def test_negative_start(self):
        c = make_counter(-3)
        assert c["get"]() == -3
        assert c["increment"]() == -2

    def test_independent_counters(self):
        c1 = make_counter(0)
        c2 = make_counter(100)
        c1["increment"]()
        c2["decrement"]()
        assert c1["get"]() == 1
        assert c2["get"]() == 99


#: make_multiplier --


class TestMakeMultiplier:
    def test_double(self):
        double = make_multiplier(2)
        assert double(5) == 10

    def test_triple(self):
        triple = make_multiplier(3)
        assert triple(4) == 12

    def test_zero_factor(self):
        zero = make_multiplier(0)
        assert zero(999) == 0

    def test_fractional(self):
        half = make_multiplier(0.5)
        assert half(10) == 5.0

    def test_negative_factor(self):
        neg = make_multiplier(-1)
        assert neg(7) == -7


#: compose --


class TestCompose:
    def test_single_function(self):
        f = compose(lambda x: x + 1)
        assert f(5) == 6

    def test_two_functions(self):
        add1 = lambda x: x + 1
        double = lambda x: x * 2
        f = compose(add1, double)
        assert f(3) == 7  # double(3)=6, add1(6)=7

    def test_three_functions(self):
        add1 = lambda x: x + 1
        double = lambda x: x * 2
        negate = lambda x: -x
        f = compose(negate, double, add1)
        # add1(3)=4, double(4)=8, negate(8)=-8
        assert f(3) == -8

    def test_empty_raises(self):
        with pytest.raises(ValueError, match="at least one"):
            compose()

    def test_with_strings(self):
        upper = lambda s: s.upper()
        exclaim = lambda s: s + "!"
        f = compose(exclaim, upper)
        assert f("hello") == "HELLO!"


#: memoize --


class TestMemoize:
    def test_basic_cache(self):
        call_count = 0

        @memoize
        def square(n):
            nonlocal call_count
            call_count += 1
            return n * n

        assert square(4) == 16
        assert square(4) == 16
        assert call_count == 1

    def test_different_args(self):
        @memoize
        def add(a, b):
            return a + b

        assert add(1, 2) == 3
        assert add(3, 4) == 7
        assert len(add.cache) == 2

    def test_recursive_fibonacci(self):
        @memoize
        def fib(n):
            return n if n < 2 else fib(n - 1) + fib(n - 2)

        assert fib(10) == 55
        assert fib(0) == 0
        assert fib(1) == 1

    def test_cache_exposed(self):
        @memoize
        def identity(x):
            return x

        identity(42)
        assert len(identity.cache) == 1

    def test_wrapped_attribute(self):
        def original(x):
            return x

        wrapped = memoize(original)
        assert wrapped.__wrapped__ is original

