"""
Type hint utilities and generic patterns.

Demonstrates:
- Generic Result type (Success/Failure)
- Generic Stack[T]
- Protocol classes
- Type-safe parsing
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import (
    Any,
    Callable,
    Generic,
    Optional,
    Protocol,
    TypeVar,
    Union,
    runtime_checkable,
)

T = TypeVar("T")
U = TypeVar("U")


# ── Result type ──────────────────────────────────────────────────


@dataclass(frozen=True)
class Success(Generic[T]):
    """Represents a successful result containing a value.

    >>> s = Success(42)
    >>> s.value
    42
    >>> s.is_ok
    True
    """

    value: T
    is_ok: bool = field(default=True, init=False)
    is_err: bool = field(default=False, init=False)

    def unwrap(self) -> T:
        """Return the contained value."""
        return self.value

    def unwrap_or(self, default: T) -> T:
        """Return the contained value (default is ignored)."""
        return self.value

    def map(self, func: Callable[[T], U]) -> Success[U]:
        """Apply *func* to the contained value."""
        return Success(func(self.value))

    def __repr__(self) -> str:
        return f"Success({self.value!r})"


@dataclass(frozen=True)
class Failure:
    """Represents a failed result containing an error message.

    >>> f = Failure("not found")
    >>> f.error
    'not found'
    >>> f.is_ok
    False
    """

    error: str
    is_ok: bool = field(default=False, init=False)
    is_err: bool = field(default=True, init=False)

    def unwrap(self) -> Any:
        """Raise ValueError since this is a Failure."""
        raise ValueError(f"Called unwrap on Failure: {self.error}")

    def unwrap_or(self, default: T) -> T:
        """Return the default value."""
        return default

    def map(self, func: Callable) -> Failure:
        """Return self unchanged (failure propagation)."""
        return self

    def __repr__(self) -> str:
        return f"Failure({self.error!r})"


# Result is the union of Success and Failure
Result = Union[Success[T], Failure]


# ── Generic Stack ────────────────────────────────────────────────


class Stack(Generic[T]):
    """A generic LIFO stack.

    >>> s = Stack[int]()
    >>> s.push(1); s.push(2); s.push(3)
    >>> len(s)
    3
    >>> s.pop()
    3
    >>> s.peek()
    2
    """

    def __init__(self) -> None:
        self._items: list[T] = []

    def push(self, item: T) -> None:
        """Push an item onto the stack."""
        self._items.append(item)

    def pop(self) -> T:
        """Pop and return the top item. Raises IndexError if empty."""
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        """Return the top item without removing it. Raises IndexError if empty."""
        if not self._items:
            raise IndexError("peek at empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        """Return True if the stack is empty."""
        return len(self._items) == 0

    def __len__(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        return f"Stack({self._items!r})"

    def __iter__(self):
        """Iterate top-to-bottom."""
        return reversed(self._items)


# ── Protocols ────────────────────────────────────────────────────


@runtime_checkable
class Printable(Protocol):
    """Protocol for objects that can be converted to a display string."""

    def display(self) -> str:
        ...


@runtime_checkable
class Comparable(Protocol):
    """Protocol for objects that support ordering."""

    def __lt__(self, other: Any) -> bool:
        ...

    def __le__(self, other: Any) -> bool:
        ...


# ── parse_typed ──────────────────────────────────────────────────


def parse_typed(value: str, target_type: type[T]) -> Result:
    """Parse a string value into the target type, returning a Result.

    Supports int, float, bool, str.

    >>> parse_typed("42", int)
    Success(42)
    >>> parse_typed("hello", int)
    Failure("Cannot parse 'hello' as int: ...")
    """
    try:
        if target_type is bool:
            lower = value.strip().lower()
            if lower in ("true", "1", "yes", "on"):
                return Success(True)
            elif lower in ("false", "0", "no", "off"):
                return Success(False)
            else:
                return Failure(f"Cannot parse {value!r} as bool")
        elif target_type is int:
            return Success(int(value))
        elif target_type is float:
            return Success(float(value))
        elif target_type is str:
            return Success(value)
        else:
            return Failure(f"Unsupported target type: {target_type}")
    except (ValueError, TypeError) as exc:
        return Failure(f"Cannot parse {value!r} as {target_type.__name__}: {exc}")


# ── Protocol implementations for demo ───────────────────────────


@dataclass
class User:
    """Example class implementing Printable and Comparable protocols."""

    name: str
    age: int

    def display(self) -> str:
        return f"{self.name} (age {self.age})"

    def __lt__(self, other: Any) -> bool:
        if not isinstance(other, User):
            return NotImplemented
        return self.age < other.age

    def __le__(self, other: Any) -> bool:
        if not isinstance(other, User):
            return NotImplemented
        return self.age <= other.age


def demo() -> None:
    """Demonstrate type hint utilities and patterns."""
    print("\n=== Type Hint Patterns ===\n")

    # --- Result type ---
    print("1. Result type (Success / Failure)")
    ok: Result = Success(42)
    err: Result = Failure("something went wrong")
    print(f"   {ok}  ->  unwrap: {ok.unwrap()}")
    print(f"   {err}  ->  unwrap_or(0): {err.unwrap_or(0)}")

    # Map
    doubled = ok.map(lambda x: x * 2)
    err_mapped = err.map(lambda x: x * 2)
    print(f"   {ok}.map(x*2) = {doubled}")
    print(f"   {err}.map(x*2) = {err_mapped}")
    print()

    # --- Generic Stack ---
    print("2. Generic Stack[T]")
    stack: Stack[int] = Stack()
    for v in [10, 20, 30, 40]:
        stack.push(v)
    print(f"   After pushing 10,20,30,40: {stack}")
    print(f"   peek: {stack.peek()}")
    print(f"   pop:  {stack.pop()}")
    print(f"   pop:  {stack.pop()}")
    print(f"   len:  {len(stack)}")
    print(f"   iterate: {list(stack)}")
    print()

    # --- Protocols ---
    print("3. Protocol checking (Printable, Comparable)")
    alice = User("Alice", 30)
    bob = User("Bob", 25)
    print(f"   alice: {alice.display()}")
    print(f"   isinstance(alice, Printable): {isinstance(alice, Printable)}")
    print(f"   isinstance(alice, Comparable): {isinstance(alice, Comparable)}")
    print(f"   alice < bob: {alice < bob}")
    print(f"   sorted: {sorted([alice, bob])}")
    print()

    # --- parse_typed ---
    print("4. parse_typed: safe string parsing")
    test_cases = [
        ("42", int),
        ("3.14", float),
        ("true", bool),
        ("hello", str),
        ("not_a_number", int),
        ("maybe", bool),
    ]
    for value, target in test_cases:
        result = parse_typed(value, target)
        print(f"   parse_typed({value!r}, {target.__name__}) = {result}")
    print()

